'use strict';
// Versión escénica: las llegadas, las fuentes y las confrontaciones se escriben
// en el orden en que la visita puede conocerlas. No se deducen por un índice.
(() => {
 const portrait=(name,world,row,rows=3)=>({name,src:`assets/expressions-${world}.png`,row,rows});
 function section(wi,ci,rows,config){
  const w=STORIES[wi],c=w.chapters[ci];
  c.narrative=rows.map(([speaker,text,location,sceneSet],n)=>({id:`${w.id}-${ci+1}-${n+1}`,speaker,text,...(location?{location}:{}),...(sceneSet!==undefined?{sceneSet}:{})}));
  c.routeInsertAfter=c.narrative[config.anchor??1].id;
  c.routeScenes=state=>{
   if(!ci)return [];
   const first=state.choices?.[0],previous=state.choices?.[ci-1];
   const texts=[];
   if(config.routes?.[first])texts.push(config.routes[first]);
   if(ci>1&&config.echoes?.[previous])texts.push(config.echoes[previous]);
   return texts.map((text,n)=>({id:`${w.id}-${ci+1}-route-${first}-${previous}-${n}`,speaker:'Narrador',text}));
  };
  c.debate=config.debate;c.boss=config.debate.opponent;
  c.debateAfterByChoice=config.after;
  c.decision.question=config.question;
  if(config.options)c.decision.options=config.options;
  c.decision.results=config.intent;
  if(config.rounds)c.rounds=config.rounds;
  if(config.docs)c.docs=config.docs;
  c.investigationIntro=config.investigation;
  c.sceneFocus=[{x:.5,y:.5},{x:.5,y:.5},{x:.5,y:.5}];
  c.auditRevision='continuidad-2';
 }
 const round=(speaker,status,options,answer,evidence,why,wrong,kind='argument')=>({speaker,status,options,answer,evidence,why,wrong,kind});

 section(0,0,[
 ['Narrador','Belén abre una puerta entre dos estantes del Archivo. Del otro lado ves un dormitorio con cajas de mudanza. Te detenés en el umbral con tu cuaderno y golpeás el marco. La señal del regreso permanece dibujada en la primera hoja. Una chica que acomoda libros se vuelve hacia vos.','La habitación de Lía',0],
 ['player','Me llamo {{player}}. Investigo cambios que aparecen solos en los cuentos. La puerta me trajo hasta acá, pero no quiero entrar sin permiso. ¿Puedo explicarte qué busco?'],
 ['Lía','Soy Lía. Esa puerta no estaba hace un minuto. Supongo que podés explicármelo, porque si grito mi mamá va a pensar que rompí otra caja.'],
 ['Narrador','Sacás de la funda las dos cartas de ejemplo que te entregó Belén. Desde el umbral le mostrás a Lía la misma línea: «Podés irte cuando quieras» en una copia, «Debés quedarte» en la otra. Ella se acerca y toca la marca negra sin que ocurra nada. Le explicás que buscás alteraciones como esa. Ella mira tus manos, el cuaderno y la puerta imposible; después aparta unos libros. «Bueno, pasá. Pero cuidado con esa caja: todavía no sé dónde va». Entrás y te sentás en el lugar que te ofrece.'],
 ['Lía','Nos mudamos hoy. Todavía no sé dónde poner nada. En mi escuela anterior tenía una amiga, Julia. Le prometí escribirle y ahora me da miedo abrir su carta. Capaz ya se acostumbró a que no esté.'],
 ['player','¿Por eso guardaste una piedra afuera de la caja?'],
 ['Narrador','La piedra está junto a la ventana; las otras cuatro quedaron en una caja con el nombre de Lía. La chica asiente. Antes de responder, una grulla de papel entra por la ventana abierta, golpea la lámpara y aterriza sobre la piedra. Detrás aparece un niño de bufanda roja, agarrado al alféizar.'],
 ['Pipo','¡Aterrizaje casi perfecto! Soy Pipo. Perdón por la lámpara. Busco a Nilo. ¿Vieron pasar una sombra que camine sola?'],
 ['player','Primero bajá de ahí. ¿Nilo es una persona o una sombra? ¿Y por qué lo estás buscando?'],
 ['Pipo','Es mi sombra. Tiene nombre porque no le gustaba que lo llamara siempre “mi sombra”. En Nunca Siempre las sombras pueden soltarse y hablar dibujando. Dormimos junto al Gran Reloj. Al despertarme, Nilo no estaba. Encontré su lápiz roto y esta grulla.'],
 ['Narrador','Pipo se coloca bajo la lámpara. Ves su cuerpo iluminado y ningún contorno oscuro en el piso. Lía levanta una mano: la sombra de su mano se mueve con ella. No tenés que decidir todavía qué significa la diferencia; acabás de comprobar lo que Pipo describe.'],
 ['Lía','En el ala hay una frase: «No estoy perdido. Estoy buscando algo». ¿Te dejó una carta y viniste a buscarlo sin abrirla?'],
 ['Pipo','Pensé que era otro mapa. Nilo hace mapas de todo. Yo soy mejor encontrando aventuras. Esta vez necesito ayuda: se fue justo antes de que dejara de sonar la campana pequeña. Seguro la tomó él.'],
 ['player','Todavía no conocemos esa campana. Contanos dónde está, para qué sirve y qué viste vos. Después podremos hablar de una acusación.'],
 ['Pipo','Mi isla se llama Nunca Siempre. El Gran Reloj abre el camino de la noche a la mañana. La campana pequeña marca cuándo se puede subir a darle cuerda. Hoy está muda y el reloj va cada vez más despacio. Si no vuelve a sonar, mañana no va a llegar. Yo estaba durmiendo: no vi a Nilo tomar nada.'],
 ['Narrador','La puerta del Archivo sigue abierta. En el cuaderno, la señal del próximo lugar coincide con el dibujo de la grulla. Decidís seguir la pista del reloj; no es todavía una prueba de La Errata. Lía pide ir con ustedes para leer la carta de Nilo y ayudar a buscarlo.'],
 ['player','Yo voy a investigar. Vos no tenés obligación de acompañarnos, Lía. Si querés hacerlo, tenemos que avisarle a tu mamá y saber cómo volver.'],
 ['Narrador','Lía llama a su madre desde la puerta de la cocina y les presenta a Pipo y a vos. Cuando su hija pregunta cómo podrían volver, Pipo saca un cordón blanco de su bolso. La mujer reconoce los nudos: su abuela le enseñó a marcar así la vuelta de esos viajes. Pide que le muestren el paso antes de dejar salir a Lía.'],
 ['Pipo','El cordón marca la ventana de regreso. La grulla abre un paso hasta el puente de entrada de mi isla; no hay que saltar al vacío. Miren: cuando la desplegamos, aparece un escalón. Si volvemos por ese puente, el cordón nos trae acá.'],
 ['Narrador','Pipo ata un extremo del cordón al gancho interior de la ventana y despliega solo una punta del papel. Aparece un descanso de madera, firme bajo tu mano. La madre de Lía pisa la plataforma y vuelve a la habitación siguiendo el cordón. Le aclarás que todavía no sabés cuánto llevará revisar el reloj. Ella acuerda dejar abierto el regreso y te pide acompañar a su hija hasta la habitación al terminar. Lía guarda la piedra y su carta. Cruzás con tu cuaderno, Pipo recoge la parte suelta del cordón y los tres avanzan por el paso.'],
 ['Narrador','El descanso desemboca en un puente entre torres cubiertas de flores. Bajo las tablas hay nubes y cascadas; al fondo, un faro sostiene un enorme reloj. Pipo señala la torre y te deja escuchar: las campanas grandes todavía marcan la hora, pero falta la pequeña que debería responderles.','La entrada de Nunca Siempre',1],
 ['Pipo','Desde acá se va al jardín de las estatuas y, después, al muelle. Nilo suele dibujar en el jardín. El portero habrá visto si pasó.'],
 ['Narrador','Un hombre hecho de hojas levanta una barrera de ramas. Pipo intenta pasar corriendo y el portero le pide detenerse. Te pregunta quién sos y por qué viajás con él. Te presentás como investigador y pedís consultar su registro de visitas.'],
 ['El Portero de las Hojas','Puedo mostrarlo. Vi salir a Nilo al alba. Más tarde oí la campana pequeña. Después entró un hombre con un frasco vacío y salió con el frasco brillante. Recién entonces la campana quedó muda. Eso es lo que observé; no vi el contenido del frasco.'],
 ['player','Entonces tu registro no acusa a Nilo. ¿Por qué cerraste el paso?'],
 ['El Portero de las Hojas','Porque Pipo pidió permiso para capturarlo como ladrón. No voy a dejar pasar una cuerda hacia el jardín sin escuchar la razón. Pueden ir a hablar con él; necesito que quede claro qué pretenden hacer.'],
 ['Narrador','Pipo saca un cordel de su bolso, distinto del que marca la ventana de regreso. Dice que era para traer a Nilo si no quería volver. Lía se queda junto al banco de la entrada en vez de seguirlo. La investigación acaba de encontrar un problema concreto: Pipo quiere convertir una sospecha en una captura.'],
 ['Lía','Yo vine a ayudar a encontrarlo, no a agarrarlo sin preguntarle. Y todavía no sabemos por qué se fue.'],
 ['Narrador','Te sentás con Pipo antes de discutir. La grulla sigue cerrada en su mano. Cuando le pedís permiso para abrirla por completo, ves que debajo guarda una postal de Mara. Pipo explica que Mara fue su compañera de viajes y regresó a su casa para estar con su familia. La primera frase dice que no volverá ese invierno.'],
 ['Pipo','Empezó diciendo eso y no quise seguir leyendo. Después se fue Nilo. Si los dejo elegir, terminan olvidándose de mí. ¿Vos también vas a dejar de ayudarme si resulta que me equivoqué?'],
 ['player','Voy a seguir investigando, pero eso no significa aceptar una acusación sin pruebas. Leamos lo que dejaron escrito. Después te voy a pedir que expliques por qué querés llevar una cuerda al jardín.'],
 ['Narrador','El portero pone su registro sobre una mesa baja. Pipo te entrega la grulla y la postal: son suyas, y acepta que las leas para comprobar lo que está diciendo. Tenés tres fuentes distintas y una pregunta delimitada. Aún no sabés quién robó la campana ni si existe un foco de La Errata en la isla.']
 ],{
  anchor:21,
  investigation:'En la mesa de la entrada tenés la nota que Nilo dejó, el registro del portero y la postal que Pipo no terminó de leer. Abrí cada documento para separar lo que ocurrió de lo que Pipo supone. Después vas a decidir cómo acompañar la búsqueda y discutir con él su pedido de captura.',
  question:'Pipo sigue sosteniendo el cordel. ¿Qué compromiso asumís antes de discutir su acusación?',
  options:['Buscar a Nilo para escucharlo y seguir por separado la pista del frasco.','Prometer a Pipo que vas a ayudar a recuperar la amistad tal como era antes.','Aceptar que Pipo lleve el cordel para intentar traer a Nilo por la fuerza.'],
  intent:['Le decís que vas a ayudar a buscar, no a capturar por una sospecha. Pipo no está de acuerdo todavía; acepta escuchar las tres fuentes antes de pedir al portero que abra el camino.','Le prometés una amistad como la de antes para que se calme. Pipo se aferra a esa promesa. Aun así, no puede pasar hacia el jardín hasta responder al registro que contradice su acusación.','Aceptás llevar el cordel. Lía te dice que eso no demuestra que Nilo haya robado nada. El portero mantiene la barrera mientras vos y Pipo contrastan lo que saben.'],
  debate:{opponent:'Pipo',portrait:portrait('Pipo','sombra',1),reason:'Pipo quiere capturar a Nilo por el robo de la campana. Vos necesitás separar la desaparición de la sombra, el robo y el miedo a otra despedida antes de continuar.',opening:'Pipo mantiene su pedido ante el portero. Vos llevás la discusión; Lía y el portero participan como testigos. No discutís contra el registro del portero: lo usás para contrastar la acusación de Pipo.',finding:'Pipo retira la acusación de que Nilo robó la campana al salir. El portero abre el camino para una búsqueda. El hombre del frasco sigue sin identificar y la voluntad de Nilo debe escucharse en el jardín.',infection:'Este debate no prueba que Pipo ni Nilo porten La Errata. Una acusación infundada demuestra un error y puede causar daño, pero no equivale a una prueba de infección.'},
  rounds:[
   round('Pipo','«Nilo salió antes de que yo notara el silencio. Con eso me alcanza para decir que se llevó la campana». El portero mantiene abierto su registro; no cambia su testimonio.',['Tu despertar no fija la hora del robo: el portero oyó la campana después de ver salir a Nilo.','Salir primero demuestra que Nilo causó cualquier problema posterior.','El portero nunca oyó ninguna campana.'],0,1,'Le señalás dos entradas del registro. Pipo baja el cordel: «Entonces pudo irse antes de que pasara otra cosa». El orden debilita su acusación, aunque todavía no identifica por sí solo al ladrón.','Buscá qué ocurrió entre la salida de Nilo y el silencio. No hace falta suponer que el portero miente para comparar esas horas.','evidence'),
   round('Pipo','«Bueno, quizá no tomó la campana. Pero está perdido. Tengo que traerlo aunque se resista». Vos abrís el ala completa de la grulla.',['La carta pide que nadie averigüe dónde está.','Nilo escribió que eligió salir y dejó un destino: el jardín de las estatuas.','Todo el que busca algo desconoce dónde está.'],1,0,'Leés «voy al jardín» y «no me busques como a una cosa». Pipo admite que no había leído esa parte. Ahora tenés una razón para buscar una conversación, no una justificación para capturarlo.','Distinguí «buscar algo» de «estar perdido». La nota incluye un destino y una petición concreta.','argument'),
   round('Pipo','Pipo deja la grulla en la mesa, pero señala la postal: «Mara eligió volver a casa y dejó de ser mi amiga. Si Nilo elige, va a pasar lo mismo».',['La primera frase de la postal borra lo que viene después.','Mara promete no crecer jamás.','La postal dice que sigue siendo su amiga y que puede escribirle aunque ese invierno se quede en casa.'],2,2,'Pipo lee la postal hasta la última línea. No se alegra de golpe; pregunta si puede contestarla después de buscar a Nilo. Su miedo sigue presente, pero la carta no sostiene la conclusión que había usado para pedir una captura.','La pregunta no exige que Pipo deje de extrañar. Exige leer si Mara escribió que ya no lo quiere.','argument')
  ],
  after:['Pipo guarda el cordel y lleva el lápiz verde que Nilo pidió. Le aclarás que no podés asegurar una reconciliación. El portero abre la barrera hacia el jardín y Lía camina a tu lado. Van a escuchar a Nilo; después seguirán al hombre del frasco.','El portero abre el camino de conversación y Pipo guarda el cordel. Al cruzar repite que vos prometiste recuperar lo de antes. Lía te recuerda en voz baja que Nilo no participó de esa promesa. La búsqueda continúa con esa expectativa pendiente.','El portero deja cruzar a los viajeros, pero advierte a Nilo que Pipo lleva un cordel. No convierte tu permiso en una orden legítima de captura. Lía te acompaña para que Nilo tenga otra persona a quien acudir si necesita negarse.']
 });
 section(0,1,[
 ['Narrador','Al salir de la entrada tomás el sendero que señaló el portero. Pipo reconoce los escalones; Lía camina detrás de vos y sigue viendo el cordón de regreso sobre el primer puente. Después de una subida corta aparecen las estatuas que la carta de Nilo nombraba como destino.','El sendero del jardín',0],
 ['Narrador','Junto a un banco hay dibujos de carbón. Ves la ventana por la que cruzaron, las dos torres de la entrada y una sombra que firma un mapa con un lápiz verde. Pipo se detiene antes de pisarlos. Del otro lado del banco aparece una figura oscura, separada de cualquier cuerpo.','El banco de Nilo',0],
 ['player','¿Sos Nilo? Leímos tu carta. Soy {{player}}, investigo lo que está pasando con el reloj. No vimos que te llevaras la campana y el registro del portero contradice esa acusación. Queremos escuchar tu versión.'],
 ['Narrador','Nilo no responde con una voz. Apoya dos dedos sobre el carbón y las letras se mueven hasta formar una frase. Pipo ya te había explicado que así hablan las sombras de la isla. Esperás a que termine; Lía se sienta lo bastante lejos para no tapar lo que escribe.'],
 ['Nilo','No me llevé la campana. Salí porque quería dibujar un camino sin que lo eligieran por mí. Pipo dice que encuentra mis mapas y después los llama sus aventuras. No quiero dejar de verlo. Quiero poder decir que algunas ideas son mías.'],
 ['Pipo','Yo pensaba que hacerlas juntos era lo importante. No sabía que te importaba tanto la firma.'],
 ['player','Ahora lo está explicando. ¿Querés escucharlo antes de decidir cómo va a volver? Nilo, ¿por qué dibujaste la ventana de Lía?'],
 ['Nilo','La vi desde las islas cuando nos acercamos al pueblo. Guardó una piedra que no servía para volar ni abrir puertas. Pensé que entendería que un dibujo importa aunque no ayude a ganar una aventura. Puse su ventana en la grulla para que Pipo encontrara a alguien que leyera lo que yo no sabía decirle.'],
 ['Lía','La piedra era del lugar donde se sentaba Julia en el recreo. La traje para acordarme de ella. Tu mapa tampoco es una cosa que dejó de servir porque Pipo ya conoce el camino.'],
 ['Narrador','Nilo hace sitio en el dibujo para que se sienten los cuatro. No te pide decidir quién merece una amistad; te muestra ejemplos concretos. Una ruta bajo unas raíces tiene su firma tachada. Pipo admite que la mostró como propia. Antes de que pueda explicar por qué, un crujido interrumpe la conversación.'],
 ['Narrador','Tres tablas caen de la pasarela que cruza el barranco del jardín. Al otro lado queda una anciana con una caja de semillas. Nilo escribe su nombre: Sila, la jardinera. Ella venía a guardar las semillas y ahora no puede regresar a su casa por el camino habitual.','La pasarela rota del jardín',1],
 ['Sila','¡No pisen las tablas sueltas! Estoy bien de este lado. Si van a ayudar, primero miren las marcas del carpintero. El barranco no se arregla apurándose.'],
 ['Pipo','Puedo saltar con ella en brazos. O usar esas tablas doradas; parecen nuevas. Nilo conoce otro paso, pero lo cerramos cuando había huevos en un nido.'],
 ['player','No vamos a levantar a Sila sin preguntarle ni a probar una tabla con ella encima. Nilo, ¿tu mapa marca una ruta revisada? Sila, ¿podés dejarnos leer tus notas antes de movernos?'],
 ['Narrador','Nilo señala una raíz ancha que pasa por debajo del puente, lejos del agua. Sila deja caer una bolsita atada a una cuerda; la alcanzás desde tu orilla. Adentro están su libreta de riego y una carta que llevaba para enviar por el barco del muelle. En la cara interior del puente encontrás además la placa con las señales de seguridad.'],
 ['Sila','La carta no es una instrucción para cruzar. Se me mezcló con las notas. Podés apartarla, aunque no me molesta que la lean. Iba a pedirle a mi hijo que viniera el jueves.'],
 ['Lía','¿Tu hijo vive lejos? Si no podés llegar al muelle, podemos llevar tu carta cuando elijamos un camino seguro.'],
 ['Sila','En otra isla. Gracias, pero primero quiero volver a este lado con mis semillas. Después les daré el sobre para el barco. Nilo, mostrame por dónde pensabas pasar.'],
 ['Pipo','Si usamos mi idea de las tablas doradas, yo podría llevar las semillas. Así Sila no tiene que decidir nada.'],
 ['Nilo','La raíz es mi mapa. Quiero explicar por dónde se pisa. Puedo ayudar y también pedir que me escuchen.'],
 ['player','La ayuda se va a acordar con Sila. Primero voy a comparar las fechas del nido, las marcas de madera y tu plano. Después discutiremos la ruta que propone Pipo. No es una acusación de infección; se trata de no lastimar a una persona por una idea mal comprobada.'],
 ['Narrador','Pipo espera en la orilla. Extendés el plano sobre una piedra y apoyás a su lado la libreta que Sila hizo llegar en la bolsa. La placa de las señales está a un paso, fijada al poste. Nilo toca su firma y Sila te pide leerla antes de que alguien explique por dónde va a cruzar.']
 ],{
  anchor:1,
  routes:['Pipo muestra el lápiz verde antes de acercarse al banco. Nilo reconoce que volvieron sin pedir una captura y deja el carbón en el suelo. Eso facilita que empiece a escribir; no significa que haya decidido retomar los viajes.','Pipo anuncia que vos vas a conseguir que todo vuelva a ser como antes. Nilo se coloca detrás del banco y escribe una pregunta: «¿Antes de qué?». Le pedís que explique qué necesita ahora, sin tratar la promesa que hiciste como si fuera un acuerdo suyo.','Nilo ve el cordel que el portero le advirtió. Mantiene el banco entre Pipo y él. Para comenzar la conversación le mostrás las manos vacías; la cuerda sigue siendo un motivo para desconfiar, aunque el registro haya descartado la acusación inicial.'],
  investigation:'Nadie cruzó la pasarela todavía. Compará la libreta, la placa y el plano identificado por Sila para decidir qué ruta se puede explicar con pruebas. La carta familiar está dentro de la misma carpeta, pero no reemplaza una señal de seguridad.',
  question:'Nilo pide explicar su mapa y Pipo se adelanta para presentarlo como propio. ¿Cómo organizás la ayuda?',
  options:['Dar la palabra a Nilo y pedir a Pipo que compruebe las marcas con vos.','Explicar vos el mapa para resolver la urgencia sin discutir su autoría.','Anunciar que el mapa es de Pipo para evitar que se entristezca.'],
  intent:['Le pedís a Nilo que prepare su explicación. Pipo debe responder primero por qué prefiere las tablas doradas a la raíz revisada. No se ha dado aún el primer paso sobre el barranco.','Te ofrecés a explicar el mapa de Nilo sin dejarlo presentar la idea. La urgencia puede resolverse, pero estás repitiendo una decisión sobre él. Aún necesitás demostrar que el camino es seguro.','Le atribuís el plano a Pipo. Nilo conserva su firma visible sobre el papel y se aparta. Sila pide resolver la seguridad del cruce antes de discutir a quién agradecerá.'],
  debate:{opponent:'Pipo',portrait:portrait('Pipo','sombra',1),reason:'Pipo propone una ruta que no corresponde a las marcas y pretende explicar un mapa que no hizo. Vos necesitás una forma segura de ayudar a Sila y una identificación honesta del plano.',opening:'Sila espera en su orilla. Vos contrastás la propuesta de Pipo con documentos; Nilo señala el trazado y la jardinera decide si acepta la ayuda. Ganar la discusión no permite cargarla contra su voluntad.',finding:'La raíz ancha permanece seca y tiene revisión azul; las tablas doradas están agrietadas. El nido vacío puede conservarse sin cerrar toda la ruta. El plano pertenece a Nilo.',infection:'No se observa una alteración de texto durante este debate. La imprudencia de Pipo y el problema de la firma necesitan corregirse, pero todavía no permiten declararlo portador.'},
  rounds:[
   round('Pipo','«El paso se cerró cuando había huevos. Entonces sigue cerrado hoy». El plano llega a la raíz, pero antes hay que comprobar si la razón original del cierre sigue presente.',['El registro termina el día primero.','La libreta registra cambios posteriores: los pájaros volaron y el nido quedó vacío antes de hoy.','La única solución es arrancar el nido.'],1,0,'Ordenás las anotaciones y Pipo reconoce que estaba usando la primera como si las siguientes no existieran. Sila confirma que hoy es día quince. La raíz puede revisarse sin tocar el nido.','Compará las fechas, no borres la primera ni te quedes solo con ella. La última observación describe una situación posterior.','evidence'),
   round('Pipo','Pipo cambia de propuesta: «Entonces pisemos las tablas doradas. Si se ven tan nuevas, deben ser más resistentes que una raíz».',['Las rayas rojas advierten grietas; los círculos azules, no el dorado, indican una revisión.','La pintura dorada siempre refuerza la madera.','Se puede tapar la raya roja para que no exista.'],0,1,'Mostrás la placa y luego las rayas de las tablas. Pipo deja de usar el brillo como prueba. La pasarela de la raíz conserva sus círculos azules y no tiene esas grietas.','La placa asigna un significado a cada señal. Elegí la señal que habla de revisión, no la que solo describe un color.','argument'),
   round('Pipo','«Si yo lo explico, da lo mismo decir que el mapa es mío». Nilo mantiene la punta del lápiz sobre la firma. Sila pregunta quién trazó el paso que va a usar.',['Usar un mapa borra a quien lo dibujó.','El plano y la anotación de Sila identifican a Nilo; Pipo puede ayudar sin cambiar la firma.','No puede haber dos personas colaborando.'],1,2,'Leés la anotación y Pipo reconoce que no había dibujado la raíz. Sila recibe una explicación que puede comprobar y sabe a quién preguntar si necesita precisar el recorrido.','La firma no es un premio para quien hable más fuerte. El documento identifica un trabajo concreto.','argument')
  ],
  after:['Nilo explica por escrito cada apoyo de la raíz. Comprobás las marcas con Pipo desde esta orilla; Sila acepta caminar por el paso y Nilo le alcanza la caja cuando llega. La jardinera le agradece por su nombre. Ya a salvo, te indica que el sendero al muelle continúa detrás de su cobertizo.','Mostrás a Sila el recorrido dibujado por Nilo y ella acepta cruzar. El peligro inmediato queda atrás, pero la sombra no tuvo ocasión de explicar su propia ayuda. Guarda el lápiz antes de señalar el sendero al muelle que Sila necesita usar para enviar su carta.','Sila cruza por la raíz después de verificar sus apoyos. «Gracias por el mapa, Nilo. Sé quién lo dibujó», dice, mirándote antes de dejar la caja. Nilo no responde: tapa su firma con carbón y camina unos pasos apartado. La corrección de Sila no borra que vos intentaras dar su trabajo a Pipo. El cruce queda resuelto; la confianza, no.']
 });
 const garden=STORIES[0].chapters[1];
 garden.docs[2].title='La carpeta de Sila y el plano firmado';
 garden.docs[2].text='Sila adjuntó a su carta un plano para que quien lleve el correo reconozca el nuevo paso. Debajo de la raíz se lee «Dibujado por Nilo el día doce». Sila escribió: «Comprobamos juntos la raíz seca y sus marcas azules. Pipo ayudó a traer las cuerdas, no dibujó este recorrido». La carta dice: «Hijo: me gustaría que vinieras el jueves. Si no podés, escribime qué día te queda bien. El jardín tiene agua y raíces. La que te extraña soy yo. Te quiero aunque este jueves no vengas». El plano permite identificar a quien debe explicar el camino; el cariño de la carta no es una orden de visita.';
 garden.docs[2].clue='El plano está firmado por Nilo; la anotación de Sila distingue su trabajo de la ayuda de Pipo.';

 section(0,2,[
 ['Narrador','Desde el cobertizo de Sila seguís el camino señalado hacia el muelle. Llevás su carta cerrada para entregarla al correo del barco, con permiso de la jardinera. Nilo camina junto a las sombras de los árboles. Desde el último escalón del sendero Nilo señala al hombre del frasco que describió el portero.','El camino al muelle',0],
 ['Nilo','Lo vi esta mañana. Hablaba junto a la torre y llevaba un frasco vacío. Ahora está esperando un barco. Ese brillo azul no estaba antes.'],
 ['Narrador','Te detenés antes de entrar al barco. El hombre deja un sobre en la mesa de embarque, entrega un pasaje al capitán y espera al extremo del muelle. La embarcación continúa amarrada. Desde esa mesa se puede observar al pasajero sin acercársele ni perderlo de vista.','El muelle de las campanas',1],
 ['player','Soy {{player}}. Investigo por qué quedó muda la campana del Gran Reloj. El portero vio a ese pasajero salir de la torre con un frasco brillante. Queremos preguntarle qué llevaba. ¿A dónde lo llevan y con quién podemos hablar de los horarios?'],
 ['Horacio','Soy Horacio, el capitán. Lo llevo al faro, antes del amanecer. Los horarios son asunto mío y no discuto los equipajes de mis clientes. Tengo un contrato.'],
 ['Narrador','Pipo señala los relojes que cuelgan del abrigo de Horacio. El capitán intenta responder con solemnidad y uno de los relojes toca otra hora. Lía sonríe, pero vos no confundís ese detalle con una prueba del robo. Le mostrás el registro del portero: interesa una pieza pública del reloj, no cualquier pertenencia del viajero.'],
 ['Horacio','El pasajero se llama Teo. Cuida el faro. Si tomo su dinero y después me niego a llevarlo, voy a perder el encargo. Mi tripulación quiere regresar antes del cumpleaños de mi hija. No es una travesura.'],
 ['player','Justamente por eso quiero leer qué te obliga a hacer el contrato, no decidirlo por una frase. Si el viaje pone en riesgo el amanecer, también perjudica a tu tripulación.'],
 ['Narrador','Horacio deja consultar el contrato sobre la mesa del muelle, sin darte aún permiso para subir. Un muchacho con delantal llega desde la cocina del barco y se presenta: Damián. Trae la carta que Teo dejó entre los papeles de embarque y pide que alguien la lea antes de zarpar.'],
 ['Damián','El sobre quedó abierto cuando compró el pasaje. Pensé que era la lista de comida. Dice que quiere guardar el sonido del Gran Reloj para que mañana no llegue. No quería meterme con un pasajero, pero no puedo fingir que leí otra cosa.'],
 ['Narrador','El capitán mira la lista y a Teo, todavía visible al final del muelle. Permite copiarla delante de él, pero exige devolver el original a la mesa de objetos del pasajero. Lía y Damián leen la misma línea con vos; no la sustituís por una acusación sobre su aspecto.'],
 ['Horacio','Conozco a Teo desde que trabajaba aquí con su hermano. El menor salió a conocer otras islas. Teo empezó a guardar canciones para no extrañarlo tanto. Seguro su hermano le pidió conservar el faro como estaba.'],
 ['player','¿Eso lo pidió su hermano o lo estás suponiendo? La lista lleva una nota adjunta. Podemos compararlas antes de repetirlo.'],
 ['Narrador','La nota es reciente y menciona una visita. Damián la copia junto a la lista antes de devolver el original a la mesa del pasajero. Pipo se inclina a leer la copia con Lía. Buscás en las palabras del hermano el pedido que Horacio acaba de atribuirle. La nota y la lista tienen autores distintos: necesitás compararlas antes de decidir cómo intervenir en el viaje.'],
 ['Pipo','Si el hermano lo quisiera, volvería para quedarse. No tendría que dejarlo otra vez.'],
 ['Narrador','Aparece una marca negra en la copia que Pipo está leyendo. Le pedís que no la toque. Delante de Lía y Damián, «volver de visita» empieza a cambiar por «quedarse». El original de la nota, devuelto junto a Teo a varios pasos, conserva su texto. Es la primera alteración visible que presenciás en este mundo.'],
 ['player','Damián, anotá qué estaba junto a cada persona. No vamos a llamar a Pipo portador por una sola coincidencia. Conservemos una copia con tres lectores y busquemos otra situación donde comparar.'],
 ['Narrador','Pipo se aparta de la mesa, sorprendido. La tinta se detiene. Anotás la distancia y la hora junto a la frase que pronunció. Después volvés a mirar al pasajero del frasco, que permanece en el extremo del muelle. Tenés dos líneas de investigación y todavía no sabés qué relación hay entre ellas.'],
 ['Narrador','Horacio prepara el embarque y protesta porque no encuentra la cuerda de la compuerta. Delante de los marineros que cargan las cajas, señala las tijeras de Damián y lo acusa de cortarla. El muchacho explica que cortó una cinta de regalo. Te muestra la cuerda enrollada detrás del timón, donde Horacio había puesto su sombrero. Está entera.'],
 ['Horacio','Estaba seguro de que faltaba. Voy a disculparme. Pero no quiero que usen un error mío para decir que no sé llevar mi barco.'],
 ['player','No vamos a confundir esa equivocación con el robo de Teo. Necesitamos un registro preciso de cómo pasó, porque acabás de exigir obediencia a tu primera impresión. Damián también tiene derecho a que no se mantenga una acusación después de encontrar la cuerda.'],
 ['Narrador','Damián escribe las horas mientras aún están en el muelle. Deja secar la tinta y ofrece sopa en platos pequeños antes de la salida. Cuando Lía pregunta por las notas en su manga, explica que son la receta de su madre. «La sal no sabe que estás apurado», lee Pipo, y esta vez espera a saber si el cocinero quiere reír.'],
 ['Narrador','Horacio propone terminar la discusión: los llevará al faro si prometen no hablar del contenido de la lista durante el viaje. Vos necesitás llegar al reloj, pero aceptar el silencio puede permitir que Teo continúe el plan. El desacuerdo ya tiene un motivo claro y tres documentos preparados antes de zarpar.']
 ],{
  anchor:8,
  routes:['Pipo deja el lápiz a Nilo cuando necesitan indicar un punto del mapa. Tu primer compromiso de escucharlo sigue teniendo un efecto pequeño y concreto: no le arrebata el papel para señalar el muelle.','Mientras esperan a Horacio, Pipo pregunta si Nilo va a volver con él después del faro. Nilo no responde todavía. Reconocés ante ambos que prometiste recuperar una amistad que no podías decidir por ellos. Pipo te pide una respuesta que no podés asegurar; Nilo necesita que esa promesa no se convierta en otra obligación.','Nilo se mantiene a varios pasos del bolso donde Pipo guardó el cordel. Señala al hombre del frasco desde la baranda, sin acercarse a ese bolso. La investigación avanza sin que la intención de captura que expresaron deje de preocuparlo.'],
  echoes:['El plano lleva la firma de Nilo. Cuando Damián pregunta quién dibujó la raíz, Pipo lo nombra; la ayuda que recibió Sila no le dio derecho a borrar esa firma.','Nilo lleva el plano cerrado después de que explicaras por él. Si alguien pregunta por el camino, mira primero quién va a responder. No ha recuperado de golpe la confianza porque el cruce saliera bien.','Nilo ocultó su firma después del cruce. Pipo ve la mancha de carbón y no consigue celebrar que lo llamaran autor. El mapa sigue sirviendo, pero la mentira no se borró con las tablas rotas.'],
  investigation:'El barco está amarrado y Teo continúa visible en el muelle. Horacio permite leer su contrato; Damián ofrece la lista que encontró en la mesa y su propio registro de la cuerda. Contrastá cada fuente antes de aceptar el trato de silencio.',
  question:'Horacio condiciona el viaje al silencio sobre el riesgo. ¿Qué le respondés?',
  options:['Pedir que el viaje sirva para recuperar la campana y explicar el peligro a la tripulación.','Aceptar el silencio durante el viaje y hablar con la tripulación al llegar al faro.','Prometer silencio absoluto para conseguir el pasaje aunque el plan siga adelante.'],
  intent:['No pedís romper cualquier compromiso: señalás que el contrato también menciona la seguridad de la isla. Horacio quiere defender su interpretación antes de permitir una misión de ayuda.','Aceptás no advertir aún a la tripulación. Horacio se dispone a llevarte como pasajero, pero te exige justificar qué parte del contrato creés que podría detener el plan de Teo.','Prometés guardar el secreto. Horacio escucha tu oferta; Damián se niega a embarcar a ciegas después de leer la lista. La discusión sobre el contrato debe resolverse delante de él.'],
  debate:{opponent:'Horacio',portrait:portrait('Horacio','support',4,8),reason:'El capitán quiere cumplir un encargo sin reconocer que puede ayudar a detener el amanecer. Vos necesitás acceso al faro y que el contrato no sirva como excusa para ocultar ese riesgo.',opening:'Vos preguntás y presentás las fuentes. Horacio responde como responsable del viaje. Damián y Lía contrastan lo que aparece en los papeles; Teo espera al extremo del muelle y no se finge ausente.',finding:'El contrato contiene una excepción de seguridad; la nota del hermano no pide detener el tiempo y la acusación contra Damián partió de una cuerda que no estaba cortada. Horacio debe decidir cómo cumplir su responsabilidad con esos hechos a la vista.',infection:'No se observó una alteración alrededor de Horacio. La discusión acredita omisiones y una acusación sin fundamento, no su infección. El cambio de la postal cerca de Pipo queda registrado para contrastarlo en el faro.'},
  rounds:[
   round('Horacio','«Firmé llevarlo antes del amanecer. No puedo detener el encargo aunque Teo quiera cerrar el reloj». Vos pedís revisar el alcance de esa obligación.',['El primer renglón reemplaza todas las cláusulas posteriores.','La cláusula de seguridad exige detener un viaje que ponga a la isla en peligro.','Solo importa que el capitán haya cobrado.'],1,0,'Mostrás el párrafo omitido. Horacio reconoce que el texto no le ordena transportar sin atender al peligro. La promesa a su hija no cambia esa cláusula.','Buscá la condición escrita para un viaje peligroso. Un subrayado no borra las líneas que quedaron sin subrayar.','evidence'),
   round('Horacio','Horacio busca otra justificación: «Teo lo hace por su hermano. La nota debe pedirle que nadie vuelva a irse». La nota está unida a la lista.',['La nota pide una visita y ventanas abiertas; no autoriza cerrar todos los amaneceres.','La foto de la infancia reemplaza lo que el hermano escribió ahora.','Extrañar convierte cualquier decisión en un pedido de otra persona.'],0,1,'Leés la petición de visita. Horacio admite que había confundido lo que Teo deseaba con lo que su hermano le pidió. Ya no puede presentar el plan como un favor solicitado por el ausente.','Compará la frase actual de la nota con la explicación del capitán. El afecto de una persona no se deduce solo de una foto antigua.','argument'),
   round('Horacio','«Ya admití que me equivoqué. Basta con disculparme en privado; no hace falta dejarlo ante toda la tripulación», propone Horacio. Damián pide conservar la secuencia porque la acusación se oyó en cubierta.',['Damián cortó una cinta a las ocho.','Horacio guardó la cuerda entera a las nueve.','Horacio acusó a Damián a las diez.'],0,2,'El orden muestra que Horacio tuvo la cuerda entera después del uso de las tijeras y antes de acusar al cocinero. Damián pide que quienes oyeron la acusación conozcan también esa comprobación. Horacio lee la rectificación ante los marineros y se disculpa; no vuelve a acusarlo para justificar su primera impresión.','Ordená el uso de las tijeras, la cuerda guardada y la acusación. No estás intentando demostrar otra vez que la cuerda existe: necesitás registrar qué sabía el capitán y qué escucharon los demás antes de su rectificación.','sequence')
  ],
  after:['Horacio explica a la tripulación el riesgo de la lista y conserva también la rectificación sobre Damián en el registro de embarque. El barco parte hacia el faro para ayudar a recuperar la campana; la cuerda queda disponible para la compuerta. Teo viaja a la vista, sin que eso lo obligue todavía a admitir el robo.','El barco parte. Vos conservás la lista, pero la tripulación no recibió la explicación que prometiste posponer. Horacio guarda la cuerda y pide hablar al llegar. Ganaste acceso al faro, no una ayuda informada que nunca solicitaste.','Horacio acepta tu silencio y prepara el viaje. Damián deja su objeción por escrito, sin impedir que el barco parta. Mientras todos miran hacia el faro, Teo conserva tiempo para terminar el cierre. Llegar rápido no convirtió el pacto en una protección para la isla.']
 });
 STORIES[0].chapters[2].rounds[2].sequence=['Damián cortó una cinta a las ocho.','Horacio guardó la cuerda entera a las nueve.','Horacio acusó a Damián a las diez.'];
 STORIES[0].chapters[2].rounds[2].challengePrompt='Ordená los hechos del registro de Damián para comprobar si sus tijeras explican la cuerda que Horacio creyó cortada.';
 section(0,3,[
 ['Narrador','El barco deja atrás el muelle y recorre la costa de nubes hasta el faro que ya viste desde el puente de entrada. No pasan a otro mundo: la torre pertenece a la misma isla y sostiene el Gran Reloj. Desde la cubierta podés ver su campana pequeña de bronce. Sigue colgada, inmóvil. Lo que falta es su sonido.','La costa del Gran Reloj',0],
 ['Narrador','Horacio amarra en el embarcadero de la torre. Teo baja primero con su frasco azul; vos, Lía, Pipo y Nilo lo siguen por la escalera exterior. El capitán espera en la puerta para saber qué tarea puede necesitar su barco. Damián trae la copia alterada de la nota del hermano de Teo. Durante la travesía, Pipo le prestó además la postal de Mara: Damián hizo dos copias y Lía las comparó con el original antes de guardarlas por separado. Van a servir para comprobar si el cambio del muelle se repite con otro texto.','La entrada del faro',0],
 ['Teo','Me dijeron que venían por la campanada. Soy Teo, el encargado del faro. Antes trabajaba aquí con mi hermano. Si quieren entender por qué guardé ese sonido, entren. No me lo van a quitar a golpes.'],
 ['player','No vine a golpearte. Voy a preguntarte por la voz de una campana que necesita toda la isla y por el plan que dejaste escrito en la lista del muelle. Nadie va a quedar encerrado en esta sala para que respondas.'],
 ['Narrador','Desde el umbral comprobás una segunda salida hacia la escalera. Teo no la cierra; les muestra los estantes. Hay frascos con luz tibia y etiquetas de canciones, risas y saludos. Al apoyar uno sobre la mesa se oye una grabación. La voz no conversa: repite la misma frase si lo abrís otra vez.','La sala de los frascos',1],
 ['Teo','Con permiso guardamos canciones de mi hermano. Después descubrí que un frasco podía retener también un sonido que todavía hacía falta afuera. El azul contiene la voz de la campana pequeña. El bronce quedó en la torre, pero mientras su voz esté encerrada no puede dar la señal de abrir la mañana.'],
 ['player','¿Lo retiraste vos? El portero vio que entraste con el frasco vacío y saliste con él brillante.'],
 ['Teo','Lo guardé yo. No quería otra despedida al amanecer. La gente siempre promete volver y después cambia. Pensé que, si no llegaba otra mañana, nadie tendría que irse.'],
 ['Narrador','Teo muestra una grabación de Mara. Pipo reconoce el saludo y acerca la mano, sin llegar a tomarlo. Nilo dibuja una pregunta: «¿Puede escuchar una respuesta nueva?». Teo admite que no. El frasco conserva una voz pasada; no conserva a la persona ni decide si esa persona quiere quedarse.'],
 ['Lía','Tengo una carta de Julia sin abrir. Me daba miedo que contara cosas de la escuela que ya no puedo compartir. La traje desde mi cuarto. No tengo que abrirla para probarte nada, pero quiero hacerlo ahora.'],
 ['Narrador','Le das espacio para leerla. Julia cuenta que extraña su lugar en el recreo y que empezó a sentarse con otra chica. Lía se queda callada un momento. Después guarda la carta entera, sin arrancar la segunda noticia. No se resolvió su mudanza; pudo conocer lo que su amiga escribió, en lugar de completar el silencio con lo que más temía.'],
 ['Teo','Mi hermano también escribe que me quiere. Pero si fuera suficiente no tendría necesidad de volver a partir. Su última carta está en el cajón. Leela y decime si no es más fácil guardar una voz que pueda escuchar cuando quiera.'],
 ['player','Una grabación puede acompañarte. No puede decidir por tu hermano ni por la isla. Voy a leer esa carta porque la estás usando para justificar el cierre del reloj, no para juzgar si tenés derecho a extrañarlo.'],
 ['Narrador','Al sacar la carta encontrás la etiqueta del frasco azul. Teo permite compararla, aunque evita leer una frase tachada. Damián registra la admisión de que tomó la voz de la campana. La mentira sobre Nilo tiene una prueba propia y no desaparece porque Teo haya reconocido una parte.'],
 ['Pipo','Si Nilo no se hubiera ido, no habríamos tenido que buscar ninguna ayuda. No debería poder dejarme.'],
 ['Narrador','La marca negra reaparece sobre una de las postales que trajo Damián. Le pedís a Horacio que observe a Teo junto a la ventana y a Lía que conserve la segunda copia lejos de Pipo. No le piden a nadie simular una emoción: Pipo acaba de repetir la misma exigencia y pueden registrar qué cambia realmente.'],
 ['player','Pipo, apartate un momento de la mesa. No te estoy condenando por tener miedo. Necesito distinguir si la tinta sigue al frasco, a Teo o al lugar donde se impone esa orden.'],
 ['Narrador','Pipo se aparta y el avance se detiene. Cuando vuelve a exigir que nadie elija irse, cambia solo la copia cercana. Lía, Damián y Horacio comparan sus notas y preservan las hojas antes de moverlas. Teo permaneció observado sin tocarlas. El segundo contraste permite investigar un foco distinto del robo.'],
 ['Pipo','Tengo miedo de despedirme. ¿Eso también cambia las letras?'],
 ['Narrador','La frase queda anotada y no produce otra alteración. Le explicás la diferencia: reconocer miedo y convertirlo en una orden sobre otra persona no son el mismo acto. Pipo necesita que se contenga la reescritura, no que le prohíban sentir. El Índice pide conservar las dos pruebas antes de registrar una hipótesis.'],
 ['Narrador','Un golpe del reloj interrumpe el registro. La compuerta que deja salir su mecanismo empieza a cerrarse. Teo cubre la manivela y dice que solo una sombra atada puede sostenerla para siempre. Nilo retrocede. Le pedís detener la discusión un instante para leer el manual fijado a la propia máquina.','La compuerta del Gran Reloj',2],
 ['Teo','Si no alcanzan el pestillo interior, el reloj va a detenerse. Nilo puede entrar por la sombra del engranaje. No es tanto pedirle que se quede si con eso salva a todos.'],
 ['Nilo','Quiero ayudar. No quiero convertirme en una pieza de la torre. ¿Hay una forma de salir después de abrir?'],
 ['Narrador','El manual describe una tarea repartida: devolver el sonido a la campana, girar la manivela y sostener la compuerta durante tres golpes. Un esquema muestra el recorrido de la sombra hasta el pestillo y una salida que debe mantenerse libre hasta que regrese. Le señalás ese margen a Nilo. Podés ayudar a coordinar la tarea sin ofrecer su encierro como precio.'],
 ['player','Teo, mientras sostengas la manivela no podemos probar ese procedimiento. Voy a mostrarte lo que dice el manual y a contrastar tu razón para impedirlo. La prueba sobre Pipo se registrará aparte: no te concede permiso para retener la voz del reloj.'],
 ['Narrador','Tenés las fuentes necesarias delante de los mismos testigos que vieron obtenerlas: el manual de la máquina, la carta que Teo ofreció y la etiqueta con los registros de la campanada y la tinta. Todavía no soltaron el frasco ni entró Nilo al mecanismo. El método y el trato que decidas importarán cuando el debate termine.']
 ],{
  anchor:1,
  routes:['Pipo deja el lápiz en la mano de Nilo antes de bajar. Haber comenzado escuchándolo no borra todo lo que pasó después, pero evita que la búsqueda se presente ahora como el regreso de una pertenencia perdida.','Pipo recuerda tu promesa de que serían como antes. Nilo le pide hablar de lo que sucederá en el faro antes de prometer otros viajes. La expectativa que creaste sigue abierta al llegar al lugar donde pueden recuperar el amanecer.','Nilo se queda junto a la baranda hasta que vos y Lía bajan del barco. Llevar una cuerda para capturarlo tuvo un efecto que un argumento correcto no arregló: todavía necesita un camino que no pase por las manos de Pipo.'],
  echoes:['Horacio dejó preparado un extremo de la cuerda para sostener la compuerta si el manual lo permite. Su tripulación conoce el riesgo porque decidiste hablar antes de zarpar.','Horacio te pide cumplir ahora la explicación a la tripulación que aceptaste posponer. Le mostrás la lista a los marineros en el embarcadero antes de entrar en la torre. Algunos quieren ayudar y otros prefieren cuidar el barco: haberlos transportado sin informarles no obliga a ninguno a participar.','Teo llegó con tiempo para adelantar el cierre mientras respetabas el pacto de silencio. Damián viene a registrar lo que ocurra por decisión propia; la tripulación no se presenta como una misión de ayuda que nunca le explicaste.'],
  investigation:'Teo reconoce haber capturado el sonido. Leé el procedimiento de la compuerta, la carta que usa como explicación y la etiqueta que conservan los testigos. El robo y el foco de tinta deben poder demostrarse por separado antes de decidir cómo intervenir.',
  question:'Teo no quiere soltar la manivela. ¿Qué método proponés para abrir la compuerta cuando responda a las pruebas?',
  options:['Coordinar la tarea del manual y pedir a Nilo ayuda voluntaria con una salida garantizada.','Pedir la ayuda de Nilo mientras Pipo le promete que nunca volverán a separarse.','Intentar atar a Nilo al mecanismo para asegurar que no abandone la tarea.'],
  intent:['Le explicás a Nilo cuándo puede salir y qué parte sostendrás vos. Su aceptación no se da por hecha. Teo todavía ocupa la manivela y tiene que responder por qué afirma que la atadura es necesaria.','Proponés una ayuda acompañada por la promesa de Pipo. Nilo dice que no puede prometer una amistad sin despedidas. El método técnico sigue teniendo que permitirle salir, aunque el compromiso afectivo que le piden vuelva a presionarlo.','Pedís sujetar a Nilo. Él se aparta y Lía te exige que leas la advertencia del manual. Aún no hay nadie atado ni una reparación consumada: tu intención ya afecta la confianza con la que deberán colaborar.'],
  debate:{opponent:'Teo',portrait:portrait('Teo','sombra',2),reason:'Teo retiene la voz de la campana y bloquea un procedimiento que podría recuperarla sin encerrar a Nilo. Vos debés demostrar el método posible y confrontar su justificación antes de tocar la máquina.',opening:'La discusión es entre vos y Teo, frente a la compuerta. Nilo decide sobre su ayuda; Lía mantiene las copias y los demás testigos conservan el registro. El posible foco de Pipo no vuelve inocente a Teo de un robo distinto.',finding:'Teo no demuestra que haga falta atar una sombra. Su carta no autoriza detener las mañanas y la etiqueta acredita que retiró la campanada y preparó una acusación falsa contra Nilo. Debe apartarse de la manivela y entregar el frasco.',infection:'Las alteraciones repetidas junto a órdenes de Pipo identifican el foco de La Errata. Teo responde por el robo y por la mentira aunque ese foco no sea suyo. El Índice contiene el permiso de reescritura probado; las decisiones sobre Nilo y el reloj conservan sus consecuencias.'},
  rounds:[
   round('Teo','«Solo una sombra atada puede sostener la compuerta». Teo mantiene la mano sobre la manivela y espera que la urgencia haga innecesario leer.',['Atar primero a Nilo y comprobar después.','Repartir la tarea del manual: alguien sostiene la manivela y una sombra entra y sale del pestillo.','Cerrar también la ventana del faro.'],1,0,'Le mostrás la instrucción que permite entrar y salir. Teo no puede sostener que su única solución es la que exige el mecanismo. La tarea compartida tiene un procedimiento escrito y una salida verificable.','Buscá la instrucción sobre el pestillo y la salida. Tener poco tiempo no cambia lo que requiere la máquina.','evidence'),
   round('Teo','Teo afloja la mano, pero no entrega el frasco: «Mi hermano se fue; guardar la mañana es la única forma de conservar su cariño». La carta describe un regreso de visita.',['El hermano expresa cariño y quiere seguir viajando; no pide que la isla pierda sus mañanas.','Una semilla obliga a quedarse para siempre en una casa.','Una partida vuelve falsas todas las cartas posteriores.'],0,1,'Leés el pedido de visita y la semilla que dejó para un árbol que cambie. Teo admite que su hermano no le pidió cerrar el reloj. Puede seguir extrañándolo sin presentar a toda la isla como parte de aquella promesa.','Respondé a la conclusión concreta. Comprender una despedida no exige aceptar que el cariño solo exista si nadie cambia.','argument'),
   round('Teo','«Nilo provocó todo al marcharse», intenta Teo. La etiqueta azul guarda el registro de la toma y una acusación falsa tachada.',['Nilo es culpable porque no habla con una voz como la de Teo.','Estar triste permite tomar un sonido público.','La admisión de Teo coincide con el orden del registro: él capturó la campanada y quiso que culparan a Nilo.'],2,2,'Presentás la etiqueta y la comparás con el testimonio del portero. Teo retira la acusación y deja el frasco en la mesa. No ganó una absolución por explicar su tristeza: terminó una discusión concreta sobre lo que tomó y cómo lo ocultó.','La prueba debe relacionar actos y registros. No reemplaces la admisión de quien tomó el sonido por una acusación contra quien quiso irse.','evidence')
  ],
  after:['Teo se aparta. Vos coordinás las manos de la manivela y Lía abre el frasco azul junto al bronce: la voz vuelve a la campana. Nilo acepta alcanzar el pestillo porque conserva una salida; nadie lo ata. Pipo sostiene el apoyo que le corresponde y espera hasta que la sombra regresa. Tres golpes abren otra mañana. La tarea no obliga a Nilo a reconciliarse.','Teo entrega el frasco. Vos y Lía sostienen el procedimiento del manual y la voz vuelve al bronce. Nilo alcanza el pestillo sin aceptar la promesa de permanecer siempre con Pipo. Sale antes del tercer golpe. El reloj funciona; la condición afectiva que le exigieron sigue necesitando una respuesta que ninguna máquina puede dar.','Cuando intentás cerrar el cordel, Nilo se suelta. Aun así elige abrir el pestillo durante un instante para no dejar a la isla sin mañana. Lía libera la voz del frasco y vos sostenés la manivela hasta el tercer golpe. La campana vuelve a sonar; Nilo no se queda a celebrar con quienes quisieron convertir su ayuda en prisión.']
 });
 // Regla física única: el objeto de bronce sigue en la torre. Se retuvo su voz.
 const sound=STORIES[0];
 sound.chapters[0].narrative.splice(14,0,{id:'sombra-1-sonido',speaker:'Pipo',text:'La campana de bronce sigue colgada. Lo que falta es su voz: acá un frasco del faro puede retener un sonido y dejar muda la cosa que lo producía. No sé quién usó uno; por eso necesito revisar qué pasó antes de acusar a Nilo.'});
 sound.chapters[0].debateAfterByChoice[2]='El portero exige que guardes el cordel en una bolsa cerrada. Autoriza una conversación acompañada por vos y Lía, no una captura. Escribe un aviso para Nilo en una hoja, la dobla y la entrega al pájaro mensajero que duerme sobre su barrera. El ave vuela hacia el jardín antes de que empiecen a caminar. La cuerda ya no bloquea el sendero, pero sigue teniendo consecuencias para la confianza.';
 sound.chapters[0].docs[0].text=sound.chapters[0].docs[0].text.replace('no rompí el reloj. Cuando salí, la campana pequeña todavía sonaba.','te dejo esta nota al alba, mientras todavía suena la campana pequeña.');
 sound.chapters[2].docs[1].text='La lista guarda fechas distintas. «Risa de mi hermano, cuando era pequeño: grabada con su permiso. Canción del faro: grabada entre los dos. Despedida en el muelle: no pude grabarla. Campana del amanecer: tomada sin preguntar. Próximo objetivo: guardar el sonido del Gran Reloj para que mañana nunca llegue». Junto al último renglón hay una foto de dos hermanos de edades diferentes y una nota reciente del menor: «Voy a volver de visita. No cierres las ventanas por mí». Antes de zarpar, Damián copia la lista y la nota delante de Lía y de vos. El original vuelve a la mesa junto a Teo, visible en el extremo del muelle. Al decir Pipo que alguien que quiera a su hermano debería quedarse, en la copia que tiene delante cambia «volver de visita» por «quedarse». El original conserva su texto. Pipo se aparta y el avance se detiene; Damián registra las posiciones. La grabación antigua, la visita pedida y la exigencia de permanencia no expresan una misma decisión. Esta primera observación aún necesita contrastarse en otra situación.';
 sound.chapters[2].docs[2].text='Damián deja por escrito: «A las ocho corté una cinta con las tijeras. A las nueve Horacio enrolló la cuerda entera y la colocó detrás del timón. A las diez me acusó delante de los marineros que cargaban las cajas. La cuerda seguía intacta bajo su sombrero. Se la mostré y reconoció su error». Al pie agregó: «No quiero que lo despidan. Quiero que quienes oyeron la acusación sepan también lo que encontramos». Horacio revisó las horas y escribió: «Te debo una disculpa». El capitán acepta que se equivocó, pero aún quiere limitar la rectificación a una conversación privada.';
 sound.chapters[2].debate.infection='No se observó una alteración alrededor de Horacio. La discusión acredita omisiones y una acusación sin fundamento, no su infección. El cambio de la copia cerca de Pipo queda registrado para contrastarlo en el faro.';
 sound.mystery.why='Teo tomó la voz de la campana y lo admitió. Las alteraciones de las letras se observaron en dos momentos distintos junto a órdenes de Pipo: la copia de la nota del hermano en el muelle y las copias de Mara en el faro. Los originales lejanos conservaron su texto y el avance se detuvo al apartarse Pipo. El robo ordinario y el patrón de reescritura tienen pruebas diferentes; querer a otra persona no impide que alguien intente quitarle una elección.';
 sound.chapters[3].docs[0].text=sound.chapters[3].docs[0].text.replace('soltar la campana pequeña del frasco','liberar la voz cautiva del frasco junto a la campana pequeña de bronce, que sigue colgada en la torre').replace('regresar a su dueño','volver al exterior').replace('Teo retira la campana.','Teo captura la voz de la campana en un frasco.').replace('Se encuentra la etiqueta que admite el retiro.','Se encuentra la etiqueta que admite la captura.');
 sound.chapters[3].timeline=['Teo captura la voz de la campana en un frasco.','Se encuentra la etiqueta que admite la captura.','El grupo contrasta la admisión con las visitas.'];
 sound.chapters[0].repair[1]='Separá la salida de Nilo del robo posterior de la voz de la campana.';
 sound.chapters[3].docs[2].title='La etiqueta azul y el segundo contraste';
 sound.chapters[3].docs[2].text='En el frasco de Teo se lee: «Voz de la campana pequeña. Capturada después del paso de la sombra. Conservar cerrada hasta completar el sello del Gran Reloj». La letra es de Teo. En el reverso tachó «La sombra la robó» y escribió «Si culpan a otro, nadie vendrá a preguntarme». Su admisión coincide con las visitas que registró el portero. Antes de abrir el reloj, Damián coloca dos copias de la postal de Mara. Horacio observa a Teo y Lía conserva la copia lejana. Pipo ordena que nadie elija dejarlo: cambia solo la copia próxima a él. Pipo se aparta y el avance se detiene. Al reconocer «tengo miedo de despedirme», no cambia ninguna letra. Lía, Damián y Horacio comparan y firman el registro. Una fuente prueba el robo de Teo; el contraste repetido con el del muelle identifica otro fenómeno junto a las órdenes de Pipo.';
 sound.chapters[3].docs[2].clue='Teo admitió capturar la voz; dos contrastes independientes vinculan la reescritura con órdenes de Pipo, no con el robo.';
 sound.chapters.forEach(c=>{
  const normalize=t=>t.replaceAll('robó la campana','robó la voz de la campana').replaceAll('robo de la campana','robo del sonido de la campana').replaceAll('recuperar la campana','recuperar la voz de la campana').replaceAll('tomó la campana','tomó el sonido de la campana').replaceAll('devolver la campana','devolverle la voz a la campana').replaceAll('se llevó la campana','se llevó el sonido de la campana').replaceAll('te llevaras la campana','te llevaras el sonido de la campana').replaceAll('No me llevé la campana','No me llevé el sonido de la campana');
  c.narrative.forEach(n=>n.text=normalize(n.text));c.docs.forEach(d=>{d.text=normalize(d.text);d.clue=normalize(d.clue);});
  c.decision.options=c.decision.options.map(normalize);c.decision.results=c.decision.results.map(normalize);
  for(const key of ['reason','opening','finding','infection'])c.debate[key]=normalize(c.debate[key]);
  c.rounds.forEach(r=>{r.status=normalize(r.status);r.options=r.options.map(normalize);r.why=normalize(r.why);r.wrong=normalize(r.wrong);});
  c.repair=c.repair.map(normalize);
  c.debateAfterByChoice=c.debateAfterByChoice.map(normalize);
 });
 section(1,0,[
 ['Narrador','La puerta que Belén abre para el segundo expediente desemboca junto a un molino. Al cruzarla quedás sobre el camino del bosque, con tu cuerpo, tu abrigo y el mismo cuaderno. La señal del marco permanece en una página para que puedas volver al Archivo. Dos hermanos salen del molino con una bolsa de harina.','El camino del molino',0],
 ['player','Soy {{player}}. Busco el origen de unos avisos que cambian solos en este bosque. ¿Conocen el camino a la posta?'],
 ['Alma','Yo soy Alma y él es Bruno. Nuestra mamá trabaja en la posta del pueblo, del otro lado del río. Tenemos que volver a casa con la harina, pero nos dijeron que el puente cerró por la crecida. Hay una posta pequeña de este lado donde podríamos esperar.'],
 ['Bruno','Mamá dijo que pidamos ayuda si tardamos. Mi hermana piensa que puede encargarse de todo. Yo hice un puente de ocho patas para que no se caiga ninguno más, pero no le pude mostrar el dibujo.'],
 ['Narrador','Alma baja la bolsa y le pide ver el papel. El dibujo no arregla la crecida; es una forma de compartir la preocupación. Al lado del molino encontrás un cartel viejo que señala la posta pequeña. Otro aviso, recién atado por encima, afirma que el puente cerró para siempre y que solo hay una casa segura.'],
 ['player','Esos avisos no dicen lo mismo. No podemos decidir que uno es cierto solo porque quedó arriba. ¿El molinero les dio un boletín con fecha?'],
 ['Narrador','Alma saca el papel que le entregaron al comprar la harina. Está doblado dentro de la bolsa, junto a una nota que su madre les dejó antes de la salida. No lo abrís sin permiso. Ella admite que estaba intentando apurarse para llegar antes de que empeorara el tiempo y no leyó el boletín.'],
 ['Alma','Podés leerlo con nosotros. No quiero llevarlo a cruzar si no es seguro. Tampoco quiero quedarme esperando sin saber qué hacer. Desde que papá murió siento que, si me demoro, todo lo demás se va a caer también.'],
 ['Narrador','Le pedís que empiecen por el camino inmediato, sin exigirle resolver sola cada miedo. Siguen las huellas que van desde el cartel nuevo hacia un claro cercano. Bruno conserva las migas que pensaba tirar para señalar el regreso: todavía están en su bolsillo. La posta pequeña continúa siendo una opción; van a preguntar por el aviso, no a renunciar a volver.'],
 ['Narrador','En el claro hay una casa de ventanas color miel. Su cubierta parece azúcar sobre piedra. Una mujer mayor atiende una mesa bajo el porche; detrás, una niña acomoda seis tazas para cuatro sillas. Cuando Bruno anuncia que solo quieren saber dónde esperar, la niña retira dos tazas y mira hacia el bosque.','El porche de la casa',1],
 ['Melaza','Me llaman Doña Melaza. La casa dio refugio durante otras crecidas. El camino a mi puerta es corto y la sopa de bienvenida es gratis. Les traje una tarjeta con las condiciones, para que después nadie diga que no sabía.'],
 ['Rosa','Soy Rosa. Yo guardo las llaves y preparo la mesa. Si vienen otros, puedo conseguir más sillas. ¿Van a quedarse mucho?'],
 ['player','Todavía no acordamos quedarnos. Queremos comprobar el cierre del puente y volver a la posta cuando sea posible. ¿Quién escribió el cartel nuevo?'],
 ['Narrador','Un pájaro de mazapán baja del alero y repite el anuncio de la casa. Melaza explica que el ave aprende sus carteles; no hizo una inspección del río. Cuando le pedís el nombre de quien giró el poste, ella responde que los viajeros deberían agradecer que alguien les haya dado una dirección.'],
 ['Bruno','Yo no perdí el camino por dejar migas. Todavía no las tiré. El cartel estaba torcido cuando salimos del molino.'],
 ['Narrador','Bruno abre el bolsillo y muestra el pan. El pájaro había repetido que los niños se extravían por jugar con migas, pero no los vio caminar. Registrás la diferencia entre un anuncio repetido y una observación. Eso no demuestra todavía que Melaza porte La Errata ni que el puente esté abierto.'],
 ['Alma','¿Podemos tomar la sopa mientras leemos? No quiero darle permiso a nadie para cobrarle recuerdos a Bruno.'],
 ['Melaza','Entrar no crea una deuda; ahí lo dice. Para otras noches tengo intercambios. Una historia, un recuerdo elegido... todo depende del acuerdo. Si quieren salir después de la sopa, la puerta está a sus espaldas.'],
 ['Narrador','La tarjeta confirma que la bienvenida no exige un intercambio. Vos comprobás que la puerta del porche continúa abierta; los hermanos aceptan solo la sopa ofrecida como gratuita. Rosa deja una taza entre las dos de ellos. Cuando Bruno habla de buscar a su madre, se le escapa una taza de la mano y se rompe.'],
 ['Rosa','No fue por ustedes. Es que las despedidas traen mala suerte. Voy a juntar esto. No quiero que nadie se corte.'],
 ['Narrador','Le alcanzás el recogedor que pide y no convertís su sobresalto en un diagnóstico. Antes de tomar otra decisión tenés tres fuentes con procedencia clara: los dos carteles del camino, el boletín que dio el molinero y la tarjeta que Melaza te entregó. La dueña insiste en que su casa es la única alternativa; esa afirmación sí se puede discutir.'],
 ['player','La sopa gratuita no responde lo del cartel. Voy a contrastar esos papeles con vos, Melaza. Necesitamos que nadie convierta un cierre temporal en una obligación de quedarse acá.']
 ],{
  anchor:9,
  investigation:'Los hermanos están bajo el porche y la puerta sigue abierta. Leé los avisos, el boletín fechado y la tarjeta que Melaza ofreció. Buscás saber qué ayuda existe y qué condiciones aceptó realmente cada persona; no declarar culpable a Rosa por romper una taza.',
  question:'Melaza propone registrar la estancia mientras ustedes comprueban los papeles. ¿Qué respuesta das con los hermanos?',
  options:['Dejar por escrito que no se acepta una deuda de recuerdos y conservar una copia para cada hermano.','Pedir que Alma firme por ambos para resolver rápido el alojamiento.','Aceptar las condiciones que Melaza añada después si eso evita buscar otro refugio.'],
  intent:['Pedís dos copias del acuerdo de bienvenida y explicás a ambos hermanos qué dice. Melaza aún quiere que acepten que no existe otro camino seguro. Vas a discutir esa afirmación antes de considerar una estancia distinta.','Le pedís a Alma que resuelva por los dos. Bruno protesta porque nadie le explicó qué estaría aceptando. Melaza aprovecha la prisa para insistir en que esta es su única opción.','Ofrecés aceptar condiciones posteriores con tal de quedarse. Bruno no ha autorizado entregar ningún recuerdo. Aunque propongas una salida rápida, los papeles siguen permitiendo comprobar qué prometió la dueña.'],
  debate:{opponent:'Doña Melaza',portrait:portrait('Doña Melaza','casa',2),reason:'La dueña usa un aviso sin fecha para afirmar que no hay otra salida y pretende ampliar lo que los hermanos aceptaron. Vos necesitás separar refugio temporal, comida gratuita e intercambio de recuerdos.',opening:'Vos llevás la conversación ante Melaza. El pájaro repite sus anuncios, pero no es un testigo independiente del puente. Alma y Bruno conservan sus documentos y responden por lo que realmente hicieron.',finding:'No se probó un cierre permanente del puente ni que la casa sea el único refugio. La sopa de bienvenida no autoriza una deuda. Bruno conservaba las migas; la explicación del extravío no era una observación.',infection:'Se demostró un anuncio engañoso, no una alteración de La Errata. Melaza sigue teniendo que responder por lo anunciado sin que eso permita atribuirle todos los fenómenos que aparezcan en la casa.'},
  rounds:[
   round('Doña Melaza','«El puente está cerrado para siempre. No vale la pena buscar otra posta», sostiene Melaza. El aviso nuevo no incluye fecha ni responsable.',['El boletín fechado habla de una revisión y ofrece un refugio temporal.','Que el aviso sea más nuevo vuelve verdadero cualquier plazo.','El puente debe estar abierto porque queremos cruzarlo.'],0,1,'Mostrás el boletín. Melaza ya no puede usarlo para afirmar un cierre permanente: la revisión sigue pendiente y la posta temporal existe. No se concluye que sea seguro cruzar ahora.','Elegí una fuente que informe el plazo. “Todavía no sabemos si se abrirá” no equivale a “cerrado para siempre”.','evidence'),
   round('Doña Melaza','La dueña cambia de argumento: «Pero ya aceptaron mi sopa; por gratitud deberían quedarse y ayudar con un recuerdo».',['La tarjeta separa la bienvenida gratuita de cualquier intercambio que deba aceptarse.','Comer da permiso para cambiar todas las condiciones.','Toda gratitud es una deuda de memoria.'],0,2,'Leés la condición que ella misma entregó. Agradecer no equivale a haber aceptado entregar recuerdos ni una permanencia indefinida. Melaza reconoce que la tarjeta sigue vigente.','Respondé con el alcance del acuerdo, no con si la sopa parece un regalo agradable.','argument'),
   round('Doña Melaza','Melaza señala al ave: «Repite que Bruno perdió el camino al tirar el pan. Eso explica por qué necesitaron mi casa». Bruno deja las migas sobre la mesa.',['Una frase repetida siempre equivale a un testigo.','El pan seguía en su bolsillo; el ave no vio un rastro de migas ni comprobó el poste girado.','No importa cómo llegaron porque ya comieron.'],1,0,'Relacionás el bolsillo con las huellas del poste. Melaza deja de presentar al ave como si hubiera visto la caminata. Ahora el grupo puede revisar el aviso en vez de cargar con una culpa inventada.','Preguntá qué pudo observar el ave. Repetir un cartel no transforma su explicación en algo presenciado.','argument')
  ],
  after:['Cada hermano guarda una copia que rechaza la deuda. Te disponés a acompañarlos a la posta temporal. Cuando Bruno quiere contarle a Alma cómo llamaba su padre a aquellos panes, se queda callado ante una palabra que conocía desde pequeño. Dejás la salida preparada y preguntás qué acaba de pasar antes de alejarte.','La copia quedó en manos de Alma y Bruno no participó del acuerdo. Ella intenta ayudarlo a terminar una frase sobre su padre, pero el niño no encuentra una palabra familiar. La falta no se resuelve diciendo por él lo que quiso aceptar. Necesitás investigar la sopa que acaban de tomar.','Melaza conserva tu ofrecimiento de aceptar más condiciones. Bruno no lo autorizó y te lo repite cuando descubre que no recuerda una palabra de su padre. La salida cómoda deja de parecer segura. Tenés que pedir el registro de la comida antes de permitir otro intercambio.']
 });
 STORIES[1].chapters[0].docs[1].text='El molinero entregó este boletín fechado al vender la harina: «La crecida obligó a cerrar el puente. Mañana se revisará. Hasta entonces no cruzar el río. Hay un refugio temporal en la posta del bosque, de este lado; no exige pertenencias ni recuerdos por abrigo. El resultado de la revisión se publicará con fecha y sello». Alma adjunta una nota que su madre dejó antes del viaje: «Si nos demoramos por el río, quédense juntos y pidan ayuda. No hace falta que lo resuelvan solos. Los quiero. Bruno: tu puente de ocho patas me hizo reír». El boletín informa una medida actual; la nota familiar permite saber qué ayuda les pidió buscar su madre.';

 section(1,1,[
 ['Narrador','Bruno sigue con la cuchara en la mano cuando Alma le pregunta por qué dejó la frase a medias. Ella pronuncia «barquitos», el nombre que su padre les daba a los panes torcidos. El niño puede repetir la palabra, pero no recuerda haber llamado así al pan. En cambio, reconoce la canción de amasar y marca su ritmo contra la taza.','La mesa del porche',0],
 ['player','Bruno, no voy a decirte qué deberías recordar. ¿Querés mostrarme qué parte sí reconocés? Alma, ¿podés contar cuándo lo escuchaste usar esa palabra por última vez?'],
 ['Narrador','Bruno golpea tres veces la cuchara contra la taza. Alma confirma que dijo «barquitos» camino al molino esa mañana. La ausencia apareció después de la sopa, pero esa secuencia sola no explica todavía cómo ocurrió. Pedís a Melaza revisar los ingredientes y el registro de intercambios de la bienvenida.'],
 ['Melaza','Podemos verlo en la cocina. Espejo anota lo que el horno recibe y lo que entrega. A veces un alivio pequeño deja a las personas pensando distinto. No lo llamaría una pérdida.'],
 ['Narrador','Aceptás entrar para averiguar qué tomó la casa, no para iniciar otro trato. Alma, Bruno y Rosa te acompañan. Melaza abre una puerta contigua al porche; el horno está a pocos pasos y el mismo pasillo permite volver a la salida.','La cocina de los espejos',1],
 ['Narrador','Detrás de una olla aparece un cocinero formado por reflejos. Se presenta como Espejo. No es el padre de los hermanos ni una aparición de sus recuerdos: es quien lleva el registro de esta cocina. Le pedís el asiento de la taza de Bruno y él coloca un libro sobre la mesa.'],
 ['Espejo','Aquí llamamos felicidad a lo que se cobra para aligerar una comida. Si faltó una palabra, el horno entendió que el huésped necesitaba descansar de ella. La señora guarda las firmas.'],
 ['player','Quiero leer la columna que describe lo retirado y el permiso del huésped. El nombre que le pongan al cobro no nos dice si Bruno lo aceptó.'],
 ['Narrador','Melaza deja el libro disponible y sale al patio a buscar leña. Rosa se queda junto a la ventana, Espejo lleva la olla al centro y vos seguís del lado de la mesa. Bruno pide papel para dibujar quién está en cada lugar. Aceptás: podrá servir si aparece otro cambio y todavía no sabés de qué depende.'],
 ['Rosa','Si nadie recuerda despedidas, nadie tiene que irse. No quiero que la mesa vuelva a quedar vacía.'],
 ['Narrador','Una línea negra aparece junto al recetario de la ventana. Bruno marca la posición del sol en su dibujo y te llama antes de tocar la tinta. Ves una palabra deformarse mientras la sombra de la ventana cae hacia el lado contrario. Registrás el momento; no lo confundís con haber demostrado ya quién activa el cambio.'],
 ['Espejo','La luz hace cosas raras con los cristales. No necesitan buscar otra explicación. Melaza no está adentro; puedo llamar a la dueña si quieren hablar de lo que cobró la casa.'],
 ['Narrador','Pedís que Melaza regrese. Mientras esperan, Alma busca en la bolsa de harina la receta que llevó al molino para calcular la compra. La deja frente a Bruno para comparar sus recuerdos. El niño reconoce una broma escrita por su padre, pero sigue sin recordar el nombre de los panes.'],
 ['Alma','Papá empezó a cocinar cuando perdió el trabajo del aserradero. El primer pan nos quedó tan duro que lo usamos para trabar una puerta. Después aprendimos esa receta. El sábado que anotó el chiste yo me enojé y di un portazo.'],
 ['Bruno','Dejó un pan junto a tu puerta para que lo vieras. Yo lo ayudé a hacerlo. No recuerdo todo igual que vos, pero esa parte sí.'],
 ['Narrador','Alma acerca la receta a Bruno y le pregunta si fue él quien dejó una huella de harina al lado de la broma. El niño compara sus dedos con la marca y sonríe. Cuando vuelve Melaza, Alma todavía tiene los ojos húmedos. La dueña deja otra cuchara junto a su plato.'],
 ['Melaza','Si esa tarde le duele, podemos tomarla a cambio de una merienda alegre con su padre. También puedo quitarle a Bruno lo que le pese. Ustedes dirán qué les conviene.'],
 ['player','Vos presentaste la primera sopa como gratuita. Antes de ofrecer otro intercambio vas a responder por el cobro de Bruno. Y ningún acuerdo sobre recuerdos de Alma puede darte permiso sobre los de su hermano.'],
 ['Narrador','La oferta no ejecuta nada todavía. Alma puede aceptar o rechazar un intercambio propio; Bruno conserva su negativa. Vos vas a decidir cómo intervenir y qué trato respaldar, con el asiento de la taza, la receta familiar y el dibujo de la ventana disponibles para examinar.']
 ],{
  anchor:4,
  routes:['Alma muestra su copia de la bienvenida gratuita. Haber escrito las condiciones le permite señalar exactamente qué cobro no aceptaron, aunque no evitó que la casa tomara la palabra de Bruno.','Alma intenta responder primero por los dos. Bruno le pide la copia que ella firmó y vuelve a explicar que él no aceptó perder palabras. Lo que acordaste por él en el porche no reemplaza su respuesta actual.','Melaza recuerda tu disposición a aceptar condiciones nuevas. Bruno te corrige delante de la dueña: «Yo no entregué mi recuerdo». Su negativa sigue siendo una fuente necesaria aunque contradiga el camino que elegiste.'],
  investigation:'El asiento de Bruno está abierto en la cocina. Su receta familiar permite comparar lo que recuerda y el dibujo registra dónde apareció la tinta. Separá la memoria cobrada sin aceptación del cambio visible junto a la ventana: aún no está probado que tengan una única causa.',
  question:'Melaza ofrece borrar el sábado de Alma y también las penas de Bruno. ¿Qué intervención respaldás?',
  options:['Rechazar el trato y dar espacio a que ambos expliquen sus recuerdos sin hablar uno por el otro.','Rechazar el cobro, pero pedir a Alma que oculte a Bruno lo que siente para no angustiarlo.','Respaldar que Alma entregue su recuerdo difícil y ofrezca también los de Bruno.'],
  intent:['Le pedís a Melaza responder por la primera taza antes de ofrecer otra. Alma conserva su recuerdo y acepta escuchar la versión de Bruno del sábado. Todavía falta recuperar la palabra que ya se tomó la casa.','Alma rechaza la cuchara, pero seguís aconsejándole que esconda el motivo a Bruno. Él escucha que van a decidir otra vez qué puede comprender. La investigación del cobro continúa sin que esa distancia se arregle sola.','Alma acepta entregar su propio recuerdo y vos respaldás que incluya a Bruno. Él dice que no. El intercambio aún no se ejecutó; Melaza debe responder primero por qué cree tener un permiso que sus propios documentos exigen.'],
  debate:{opponent:'Doña Melaza',portrait:portrait('Doña Melaza','casa',2),reason:'La dueña pretende convertir un cobro no aceptado en una ayuda y ofrece nuevas pérdidas como solución. Vos necesitás que reconozca lo tomado y permita buscar cómo devolverlo.',opening:'Melaza responde por el libro de su cocina; Espejo explica lo que anotó. Vos llevás las preguntas, Alma y Bruno hablan de sus recuerdos y Rosa permanece junto a la ventana donde apareció la tinta.',finding:'La casa tomó una palabra sin aceptación de Bruno. La receta no prueba que un recuerdo doloroso carezca de cariño y el dibujo no coincide con una sombra normal. Melaza debe mostrar dónde guarda los recuerdos cobrados.',infection:'Hay un cambio de tinta registrado en ausencia de Melaza y después de una frase de Rosa. Es un indicio que exige otro contraste, no una condena de la niña ni una atribución de toda la casa al virus.'},
  rounds:[
   round('Doña Melaza','«La taza le dio felicidad; no tiene sentido hablar de una pérdida». El libro puede registrar algo distinto del nombre usado para cobrar.',['El rótulo felicidad demuestra permiso.','El asiento registra una palabra retirada y deja vacía la aceptación de Bruno.','La canción prueba que todas las palabras continúan ahí.'],1,1,'Mostrás la columna y la firma ausente. Melaza admite que el horno tomó algo. Que Bruno conserve un ritmo no demuestra que no le falte ninguna palabra.','Buscá el hecho registrado y el permiso. No alcanza con cambiar el nombre del cobro.','evidence'),
   round('Doña Melaza','Melaza repite la explicación de Espejo: «La mancha solo era la sombra de una ventana. No hay otro fenómeno que investigar».',['La dirección dibujada de la luz y la tinta no coincide con una sombra normal.','Toda sombra cambia las palabras de los recetarios.','Melaza estaba dentro porque es la dueña.'],0,2,'Comparás la posición de la ventana con el avance de la tinta que Bruno registró. La explicación de la sombra no describe esa observación. Todavía falta comprobar qué provoca la alteración.','Usá la ubicación que se observó, no la que convendría a una sospecha. Melaza estaba afuera en ese momento.','argument'),
   round('Doña Melaza','La dueña vuelve a la oferta: «Si esa discusión les duele, ahí no había cariño que valga la pena conservar». Alma sostiene la receta de su padre.',['El portazo borra todas las otras frases de la hoja.','Solo las familias sin discusiones pueden quererse.','La receta conserva enojo, bromas e invitaciones a cocinar juntos; no prueba la ausencia de cariño.'],2,0,'Leés las dos letras que responden una a otra. El texto no exige que Alma deje de sentir dolor; muestra que la relación tenía más de una emoción. Melaza ya no puede ofrecer la pérdida como una conclusión obligatoria de esa prueba.','Leé también lo que respondió el padre después del desacuerdo. Una emoción no sustituye todo lo que la hoja conserva.','argument')
  ],
  after:['Melaza abre el registro de frascos y te indica el archivo bajo la escalera. Alma y Bruno conservan sus recuerdos del sábado y cuentan juntos el chiste del pan. La palabra cobrada todavía debe buscarse. Rosa trae la llave para acompañarlos al archivo.','Melaza permite buscar los frascos bajo la escalera. Alma conserva su recuerdo, pero no le explica a Bruno por qué quiso borrarlo. Él sigue ayudando con la canción, sin fingir que esa ayuda le devolvió la confianza perdida.','Alma firma y la casa toma el recuerdo propio que ofreció. Bruno mantiene su negativa: no se ejecuta un permiso sobre su mente solo porque otro lo haya propuesto. La dueña permite consultar los frascos del archivo. Alma lleva la receta, aunque ya no puede describir la tarde del portazo que dio a cambio.']
 });
 STORIES[1].chapters[1].docs[0].text=STORIES[1].chapters[1].docs[0].text.replace('La hoja conserva manchas','La hoja que Alma llevaba con la harina conserva manchas');
 section(1,2,[
 ['Narrador','Rosa usa la llave grande para abrir la puerta que Melaza señaló debajo de la escalera. Bajás tres peldaños y encontrás una mesa de archivo; detrás hay un pasillo de habitaciones. La cocina queda arriba, todavía visible desde la puerta. Venís a buscar la palabra que la casa cobró a Bruno.','El archivo bajo la escalera',0],
 ['Rosa','Los frascos están ordenados por nombre. Esa parte la lleva el Archivero. Yo guardo las llaves de los cuartos. No los abro porque la casa dice que se puede caer si la gente se marcha.'],
 ['Narrador','El Archivero de Harina es un trabajador pequeño, de manos cubiertas de polvo, que copia etiquetas según las órdenes del libro. Le pedís el nombre de Bruno. Busca el frasco correspondiente, pero el estante tiene un aviso reciente: toda devolución necesita autorización de Melaza. Necesitás saber qué instrucción original fue reemplazada.'],
 ['player','¿Podemos leer las instrucciones del edificio? La advertencia no explica por qué una habitación tendría que seguir ocupada para sostener una pared. Antes de aceptarla quiero ver qué describe el constructor.'],
 ['Narrador','El Archivero retira un plano de su cajón y permite compararlo. Después descorre la mirilla de una puerta del pasillo: ves a tres niños sentados en camas pequeñas. El pestillo continúa cerrado bajo una etiqueta de deuda. Cuando preguntás por los otros cuartos, el Archivero señala que tienen el mismo cierre. Los huéspedes pueden hablar por las mirillas, pero no salir.','Las habitaciones del archivo',1],
 ['Alma','No podemos llevarnos una palabra y hacer como si no hubiéramos visto esto. ¿Quién los está esperando?'],
 ['Nico','Yo me llamo Nico. Lo dice mi camiseta. Mi abuela me enseñó este pájaro y me trajo durante una tormenta. Cuando lo doblo me acuerdo de sus manos, pero todavía no sé volver hasta su casa.'],
 ['Narrador','Bruno se sienta frente a la puerta y pasa su dibujo de ocho patas por debajo. Nico pregunta si puede añadir otra; Bruno acepta y escucha el roce del lápiz desde su lado. Nico conserva el dibujo mientras muestra por la mirilla cómo dobla el pájaro de su abuela. Copiás ese pájaro y anotás su explicación: puede servir para buscar a su familia. Bruno dibuja otra vez su puente en tu cuaderno y añade la novena pata que propuso Nico; el original queda del otro lado de la puerta.'],
 ['Rosa','Mi hermana también me dejó acá mientras buscaba un camino seguro. Fue hace dos inviernos. Melaza dijo que tal vez había decidido vivir en otro pueblo. Si los huéspedes dejan de irse, por lo menos sé a quién voy a encontrar en la mesa.'],
 ['player','¿Tu hermana dijo que no volvería o fue una explicación de Melaza?'],
 ['Rosa','Yo no recibí ninguna carta. Preparaba una taza de más por si llegaba. Después aprendí a contar las que sí estaban. Sé que no es lo mismo que elegir una familia. No sé cómo hacer para que no se vaya también.'],
 ['Narrador','El Archivero escucha la palabra «carta» y busca un saco que debía clasificar como devuelto. Encontrás tres sobres a nombre de Rosa y una orden firmada por Melaza para retenerlos. Antes de leer los textos personales le mostrás los destinatarios a Rosa y le preguntás si quiere abrirlos.'],
 ['Rosa','Quiero saber qué pasó. No me digan que todo va a salir bien antes de leer.'],
 ['Narrador','Las cartas describen intentos de regresar, un carro roto y la crecida. La última tiene una dirección de hace dos inviernos. Leés también la fecha en voz alta. Refutan que su hermana se marchara sin intentar buscarla; no prueban lo que ocurrió desde entonces. Rosa sostiene el sobre y te pide ayuda para consultar esa dirección cuando salgan.'],
 ['Narrador','Melaza aparece en la puerta del archivo, llamada por el Archivero. No niega su firma. Dice que guardó las cartas para que Rosa dejara de sufrir esperando. Le pedís permanecer junto a Alma en la cocina mientras comparás la advertencia del edificio con el plano. Así el grupo registra dónde se encuentra cada persona.'],
 ['Rosa','No abran todavía. Si salen todos, la casa se cae y no queda un lugar donde esperar a mi hermana. Que nadie pueda elegir irse.'],
 ['Narrador','La palabra «elegir» cambia en una hoja cercana a Rosa. Bruno te lo señala. Tenés una copia del plano lejos de ella y recordás la tinta del recetario; proponés copiar una oración sencilla en dos hojas para comparar posiciones. Pedís permiso a Rosa antes de dejar una en su mesa.'],
 ['player','No voy a decidir que tu tristeza es una infección. Vamos a registrar un cambio concreto. Bruno sostendrá una copia lejos; otra quedará acá. Alma seguirá viendo a Melaza arriba. Si una frase cambia, anotaremos dónde y qué estaba pasando.'],
 ['Narrador','Escribís «Puedo querer a mi hermana y dejarla elegir». La copia de Bruno conserva la oración. Rosa vuelve a ordenar al Archivero que nadie pueda elegir irse y la copia junto a ella sustituye «elegir» por «quedarse». El Archivero anota la hora antes de tocar los papeles. Melaza sigue vigilada en la cocina.'],
 ['Rosa','Entonces esto está pasando conmigo cerca. No quiero hacerles daño. Pero si están equivocados sobre las paredes, salir puede matarnos a todos.'],
 ['player','Por eso voy a comparar el plano con vos. Lo que pide revisar el edificio y lo que cambia la tinta tienen pruebas distintas. Primero necesitamos saber si la advertencia justifica mantener cerradas las habitaciones. Después registraremos qué podemos sostener sobre el foco.'],
 ['Narrador','El Archivero propone tramitar primero la salida de Alma y Bruno y dejar pendientes las etiquetas de los otros huéspedes mientras reúne firmas. La puerta exterior queda a pocos pasos de la cocina. Rosa conserva la llave del pasillo y vuelve a señalar la advertencia de derrumbe: necesita entender el plano antes de permitir que retiren las etiquetas.']
 ],{
  anchor:2,
  routes:['Alma lleva su copia del acuerdo. Se la muestra al Archivero cuando pide la palabra de Bruno: sabe identificar un cobro que no aceptaron en vez de limitarse a pedir un favor.','La copia sigue en manos de Alma, pero esta vez Bruno responde por el nombre de su propio frasco. Después de que hablaran por él en el porche, necesita comprobar que esta búsqueda no volverá a hacerse sin preguntarle.','El ofrecimiento de aceptar más condiciones figura en la entrada, aunque Bruno nunca lo firmó. Lo dejás junto a la negativa que él repite. El archivo tendrá que conservar ambas cosas; tu promesa no debe transformarse en una aceptación inventada del niño.'],
  echoes:['Bruno y Alma comparan juntos la receta. Ella puede explicar el sábado sin convertir su recuerdo en la única versión que él deba conservar.','Bruno guarda el ritmo del pan para encontrar el frasco, pero recibe respuestas breves cuando pregunta por el portazo. La decisión de ocultar sigue separando una conversación que él quería compartir.','Alma reconoce su letra en la receta y no recuerda la tarde que entregó. Bruno explica solo lo que él conserva. No le adjudica una memoria nueva para consolarla ni permite que usen la pérdida para reclamar también sus recuerdos.'],
  investigation:'Buscabas un frasco y encontraste huéspedes encerrados. Las cartas muestran una búsqueda pasada; el plano explica la estructura; las dos hojas registran una alteración en posiciones comparadas. Leé las tres cosas sin hacer que una resuelva automáticamente las preguntas de las otras.',
  question:'El Archivero ofrece una salida parcial. ¿Qué salida y qué información respaldás?',
  options:['Abrir todas las habitaciones y entregar las cartas a Rosa sin prometer un reencuentro que aún no está probado.','Abrir las habitaciones, pero retener la última carta y condicionar a tu permiso la consulta de esa dirección.','Salir con Bruno primero y dejar pendientes las habitaciones de los demás.'],
  intent:['Pedís preparar todas las etiquetas para retirarlas de las puertas. Rosa conserva sus cartas completas. Antes de usar la llave tenés que responder a la advertencia que todavía la hace temer un derrumbe.','Preparás la apertura y proponés guardar vos la última carta hasta decidir si conviene investigar la dirección. Rosa ya conoce su contenido: lo que le estás quitando es la fuente que necesita para consultar por su cuenta. Ella pide poder conservarla aunque la respuesta no esté asegurada.','Preparás la salida de los hermanos y dejás la de los otros niños para después. Rosa aún impide abrir por miedo al edificio; resolver el argumento no te obligará por sí solo a terminar una ayuda que elegiste aplazar.'],
  debate:{opponent:'Rosa',portrait:portrait('Rosa','secondary',1,6),reason:'Rosa conserva la llave porque cree que vaciar habitaciones derrumbará el refugio. Vos necesitás contrastar esa amenaza sin inventar el destino de su hermana ni confundir la mentira de Melaza con la tinta.',opening:'Vos discutís las fuentes con Rosa. El Archivero puede leer instrucciones, pero no recibe autoridad para decidir qué futuro deben aceptar los niños. Melaza permanece en la cocina con Alma; Bruno conserva la copia lejana.',finding:'El plano no exige huéspedes para sostener la casa. Las cartas prueban una búsqueda antigua, no un reencuentro actual. La retención firmada por Melaza y la alteración cercana a Rosa son hechos diferentes que deben conservarse.',infection:'El contraste señala una alteración junto a una orden de Rosa, con Melaza observada lejos. Es un indicio fuerte; antes de contener el foco se verificará si se repite con el horno apagado y con una emoción reconocida sin orden.'},
  rounds:[
   round('Rosa','Rosa mira la dirección de la última carta: «Ya sé que es vieja. Pero me buscó tres veces. ¿No es suficiente para que me prometas que la vamos a encontrar?». Le cuesta dar el primer paso sin esa certeza.',['Las cartas antiguas garantizan cualquier presente.','Las cartas prueban que la buscó entonces y permiten preguntar por una dirección; no fijan su situación actual.','Una prueba que no responde todo no tiene ningún valor.'],1,0,'Leés la fecha con Rosa. Rosa dobla el sobre por la misma marca. «Entonces ayudame a preguntar. No me digas que está ahí si todavía no lo sabés». Acepta consultar la dirección sin convertirla en una garantía. La prueba sigue siendo importante sin ofrecer una certeza que no contiene.','Una búsqueda pasada no es igual a una ubicación comprobada hoy. Mirá qué fecha sostiene cada afirmación.','argument'),
   round('Rosa','«La advertencia dice que la casa se derrumba sin huéspedes. No puedo abrir si eso es cierto». El plano original conserva una descripción del sostén.',['El plano muestra muros de piedra y una salida independiente de las camas ocupadas.','La palabra derrumbe demuestra por sí misma una causa.','Los niños funcionan como columnas.'],0,1,'Mostrás los apoyos reales y la instrucción de quitar etiquetas de deuda. Rosa puede seguir temiendo la salida, pero la amenaza no describe cómo se sostiene el edificio. Pone la llave sobre la mesa para que preparen la apertura elegida.','Buscá una explicación material, no solo un aviso alarmante sin firma del constructor.','evidence'),
   round('Rosa','Rosa señala la orden de Melaza: «Si ella ocultó mis cartas, quizá ella cambió también la hoja desde arriba». La posición de las dos copias quedó registrada.',['Toda persona que miente es responsable de cualquier cambio posterior.','Sentir tristeza identifica por sí solo un foco.','La retención tiene la firma de Melaza, pero el cambio se produjo junto a Rosa mientras la dueña estaba observada lejos.'],2,2,'Separás la orden y el ensayo. Rosa no queda definida por una etiqueta de maldad; Melaza tampoco queda absuelta de esconder cartas porque el foco pueda estar en otro sitio. Ambas pruebas siguen abiertas para la verificación final.','Usá la comparación que hicieron. No reemplaces dos responsabilidades específicas por una acusación que lo explique todo.','argument')
  ],
  after:['Rosa entrega la llave. Llamás a Alma desde el pie de los escalones: el registro del contraste ya está firmado y puede dejar de observar a Melaza. Vos y los hermanos retiran las etiquetas de todas las puertas y ayudan a los niños a reunirse en el vestíbulo. Rosa conserva las tres cartas y una búsqueda posible, sin una promesa inventada de reencuentro. Melaza debe mostrar ahora cómo devolver los recuerdos que aún guarda.','Con el contraste ya registrado, llamás a Alma para que vuelva de la cocina. Abrís las habitaciones con la llave que Rosa entregó. Los niños llegan al vestíbulo y vos retenés la última carta en tu carpeta. Rosa puede repetir la dirección que leyó, pero necesita el original para que la posta contraste el remitente y la fecha. La liberación de los huéspedes no le devuelve ese documento ni justifica que su consulta dependa de tu permiso.','Llamás a Alma: el contraste terminó y ya no necesitás que siga observando a Melaza. Llevás a los hermanos al vestíbulo y dejás las otras habitaciones pendientes. Rosa entregó la llave, pero vos no completaste la apertura de todos los cuartos. Nico sigue esperando detrás de su puerta, con el dibujo de nueve patas que Bruno no puede traer consigo como si lo hubiera salvado.']
 });
 STORIES[1].chapters[2].docs[2].text='Vos copiás «Puedo querer a mi hermana y dejarla elegir» en dos hojas. Bruno sostiene una lejos de Rosa; la otra queda junto a ella. Alma observa a Melaza en la cocina. Rosa ordena al Archivero «que nadie pueda elegir irse»: solo la hoja de su mesa cambia «elegir» por «quedarse». La copia de Bruno conserva el original. El Archivero anota la hora antes de tocar las hojas. Alma confirma que Melaza permaneció a su vista durante el cambio. Esta comparación separa la orden de retener cartas, firmada por la dueña, de una reescritura que aparece junto a una orden de Rosa. El siguiente contraste comprobará si depende del horno o de reconocer miedo sin imponer una salida.';

 section(1,3,[
 ['Narrador','Desde el archivo subís los tres escalones y regresás al vestíbulo con Alma y Bruno. Melaza espera en la puerta de la cocina. Rosa conserva la llave y los sobres que recibió. Le pedís a la dueña volver junto al horno para consultar el mecanismo que mantiene los recuerdos en los frascos.','El vestíbulo de la casa',0],
 ['Melaza','No niego que escondí las cartas. Rosa dejó de llorar esperando una respuesta y volvió a comer. Pensé que el resultado era mejor. Ustedes también quisieron proteger a los hermanos de lo que dolía.'],
 ['player','Explicar por qué lo hiciste no muestra que Rosa hubiera aceptado perder noticias. Vamos a guardar tu orden y las cartas. Después quiero ver la receta original del refugio, porque el registro habla de devoluciones y la cocina dejó de hacerlas.'],
 ['Narrador','Melaza les permite entrar con los documentos. Rosa vuelve a la mesa y deja la llave a la vista. No está obligada a confiar en vos de inmediato: acaba de comprobar que alguien le ocultó una búsqueda que importaba. Te escucha cuando pedís una comparación más antes de registrar quién activa la tinta.','El horno de los recuerdos',1],
 ['Melaza','Al principio di sopa y cama durante una tormenta. Cuando el camino quedó libre todos salieron. Yo esperaba que eligieran quedarse. Después empecé a pedir historias por comida. Más tarde conservé recuerdos para asegurar que volvieran a buscar algo.'],
 ['Alma','Eso no es lo que prometía la tarjeta del porche. No podés decir que una bienvenida gratuita autoriza el precio que elegiste después.'],
 ['Narrador','Melaza saca del horno un libro de contratos. Debajo está la receta fundadora que Espejo utiliza para orientar los intercambios. El documento no fue creado para matar ni necesita una persona dentro del fuego: el calor procesa las cláusulas que retienen recuerdos en frascos con nombres. Le pedís mostrar también la copia del constructor.'],
 ['Espejo','La copia está en mi cajón de trabajo. Conserva la palabra «reversible», que aquí quedó tapada. Sin nombres no sabríamos a qué huésped devolver cada frasco. El horno no exige quemar esa identificación.'],
 ['Narrador','Guardás la copia con Alma y Bruno. Espejo apaga el horno para que puedan examinarlo sin un nuevo intercambio. Melaza permanece a tu lado. Frente a Rosa colocan un contrato sin ejecutar y una hoja que describe lo que sucede, para distinguir este mecanismo de la reescritura que apareció cerca de ella.'],
 ['Rosa','Tengo miedo de que, si salen, no vuelvan a elegir mi mesa.'],
 ['Narrador','La frase queda registrada y no altera el contrato. Rosa conserva la voz para explicar el miedo sin que eso la vuelva culpable por sentirlo. Cuando Melaza dice que van a abrir la salida, Rosa interrumpe al Archivero: «Que nadie elija irse». La tinta del contrato cambia con el horno todavía apagado.'],
 ['player','Detengamos las manos un momento. La primera frase reconocía tu miedo y no cambió nada. La segunda ordenó una prohibición y la tinta avanzó. Alma y Bruno, leamos el registro antes de apartar el papel.'],
 ['Narrador','Los hermanos, el Archivero y vos conservan la comparación. Coincide con las dos hojas del archivo y permite sostener una hipótesis de foco. El libro automático anotó la orden, el estado del horno y la ubicación de cada persona. El Índice puede proteger ese registro después de que tres lectores lo contrasten.'],
 ['Rosa','¿Eso significa que soy mala? También traje mantas cuando Nico estaba enfermo.'],
 ['player','Significa que tenemos que detener una reescritura que quita decisiones. Las mantas fueron una ayuda; esconder llaves lastimó a otros. Ninguno de los dos hechos borra al otro. No voy a usar tu tristeza como prueba ni a quitarte la voz para contener el foco.'],
 ['Narrador','Bruno busca su frasco por el nombre. Alma coloca el pájaro de madera que talló su padre junto a la lista de recuerdos y escribe con él una carta a su madre: irán al refugio temporal y necesitan que sepa lo ocurrido. El Archivero llama al ave de mazapán. Rosa explica que lleva correo entre las dos postas; puede cruzar volando aunque el puente siga cerrado. El ave acepta el sobre, repite solo la dirección para confirmarla y sale por la ventana. Todavía no tienen una respuesta.'],
 ['Alma','Voy a contarle que tengo miedo y que necesito ayuda. Ser la mayor no me dio permiso para decidir qué partes de Bruno era más cómodo conservar.'],
 ['Narrador','Melaza ofrece un último trato antes de retirar los contratos: una salida inmediata si los hermanos aceptan olvidar lo sucedido. También dice que, para devolver lo guardado, podrían quemar todas las etiquetas. La receta permite comprobar ambas propuestas y explica por qué perder los nombres puede impedir una restitución.'],
 ['player','Vos vas a responder por esas instrucciones, Melaza. Yo presentaré la receta y el registro; los hermanos van a hablar por sus recuerdos. Contener a Rosa no convierte en legítimas las deudas que vos conservás.'],
 ['Narrador','El horno sigue apagado y las personas permanecen fuera de él. Los frascos no se han abierto ni los contratos fueron destruidos. Vas a registrar tu hipótesis con dos fuentes y decidir qué restitución apoyar. La discusión final debe dejar claro qué se conserva, qué se retira y quién puede aceptar un intercambio.']
 ],{
  anchor:3,
  routes:['Alma recuerda que conservaron por escrito la bienvenida. La copia no evitó el abuso, pero permite exigir una devolución por un cobro no aceptado. No necesita inventar que todos entraron sin haber recibido ninguna oferta.','Bruno conserva su negativa aunque Alma haya firmado en el porche. Al volver al horno pregunta por su propio frasco. La investigación no usa la firma de su hermana como si fuera el recuerdo que él entregó voluntariamente.','Melaza muestra el ofrecimiento de aceptar condiciones nuevas. Vos tenés que reconocerlo en vez de ocultarlo para parecer la única voz correcta. Ese papel no contiene la aceptación de Bruno, pero sí una decisión tuya que perjudicó la búsqueda de límites.'],
  echoes:['Los niños cuyas habitaciones abriste esperan juntos en el vestíbulo. Rosa tiene las tres cartas. La tarea que falta es devolver recuerdos e investigar una dirección, no fingir que salir de una habitación reparó ya todo el pasado.','Los niños están en el vestíbulo y Rosa conserva un sobre vacío. Te vuelve a pedir la carta que retuviste en el archivo: no quiere que alguien vuelva a decidir cuándo puede consultar una noticia de su hermana. Todavía la llevás en tu carpeta.','Los hermanos llegaron al vestíbulo, pero las otras puertas siguen pendientes. Bruno oye a Nico desde el pasillo. La discusión final también deberá hacerse cargo de quienes dejaste esperando, no celebrar una liberación que todavía no completaste.'],
  investigation:'La receta fundadora explica cómo devolver sin perder nombres; el registro compara miedo y órdenes con el horno apagado; la carta de los hermanos pide ayuda sin hablar uno por el otro. Contrastá esos alcances antes de elegir qué contratos retirar.',
  question:'Melaza ofrece una salida inmediata a cambio de olvidar. ¿Qué instrucción de devolución respaldás?',
  options:['Devolver los recuerdos con sus nombres y permitir que cada huésped elija dónde ir.','Abrir la salida, pero conservar contratos para exigir cooperación hasta terminar.','Aceptar el olvido de lo ocurrido y salir con los hermanos dejando la restitución pendiente.'],
  intent:['Pedís preparar los nombres junto a sus frascos y sacar del horno los contratos que bloquean la restitución. Todavía deben responderse las objeciones de Melaza antes de ejecutar el procedimiento.','Proponés conservar una parte del poder de retención para asegurar ayuda. Rosa reconoce la condición que la casa usaba. Aunque una puerta pueda abrirse, estás decidiendo quién seguirá necesitando permiso después.','Respaldás el intercambio rápido pese a la negativa anterior de Bruno. Alma quiere salir y Melaza presenta el contrato. La casa podría ejecutar un nuevo daño; que elijan una prisa no vuelve voluntarios todos los recuerdos incluidos.'],
  debate:{opponent:'Doña Melaza',portrait:portrait('Doña Melaza','casa',2),reason:'La dueña pretende conservar control o destruir identificaciones al devolver recuerdos. Vos necesitás establecer el método y la responsabilidad antes de que el último contrato vuelva irreversible la pérdida.',opening:'Vos contrastás las instrucciones de Melaza con la receta y los registros. Rosa participa como persona afectada y posible portadora; su diagnóstico no sustituye las pruebas de los cobros ordinarios de la dueña.',finding:'Devolver requiere conservar nombres y retirar contratos; la tinta responde a órdenes de Rosa que niegan salidas, no a su tristeza ni al horno encendido. Comprender la soledad de Melaza no cancela su deber de devolver y responder por las cartas.',infection:'Los dos contrastes y el registro independiente sostienen el foco de Rosa. El Índice bloquea el permiso que reescribía las decisiones. La niña no pierde su memoria ni su voz; las deudas, la restitución y la libertad de los huéspedes dependen de lo que se haga con la casa.'},
  rounds:[
   round('Doña Melaza','«Para salvar los recuerdos hay que quemar todas las etiquetas», propone Melaza. La copia fundadora distingue nombres y contratos.',['Quemar cualquier papel facilita devolverlo todo.','Los nombres identifican a cada dueño; se retiran los contratos que bloquean la devolución.','Cambiar nombres por números devuelve las memorias solas.'],1,0,'Mostrás la instrucción que mantiene los nombres junto a los frascos. Melaza reconoce que quemarlos no forma parte del procedimiento de devolución y podría impedirlo.','No todo papel cumple la misma función. Leé qué identifica un recuerdo y qué lo retiene.','evidence'),
   round('Doña Melaza','«Rosa lloró y por eso cambió la tinta; el horno no tiene otra explicación». El registro conserva una emoción sin cambio y una orden con cambio.',['El cambio sigue la prohibición de elegir, incluso con el horno apagado; reconocer miedo no lo activó.','Cualquier llanto demuestra una infección.','Basta encender el horno para producir cada alteración.'],0,1,'Comparás los momentos que presenciaron. Melaza no puede reemplazar el contraste por la apariencia de una niña triste. La hipótesis se sostiene por cambios observables y condiciones registradas.','Buscá qué diferencia las situaciones del registro. No uses una emoción como atajo para identificar culpables.','evidence'),
   round('Doña Melaza','Melaza deja de discutir el mecanismo: «Si comprendieron por qué no quería quedarme sola, no deberían pedirme que responda por las cartas».',['Comprender una soledad obliga a entregar todas las llaves.','Una explicación vuelve inexistentes las cartas retenidas.','Se puede tratarla con dignidad y exigir restitución y una respuesta por lo que decidió.'],2,2,'Le pedís responder sin insultarla ni absolverla. Alma y Bruno pueden reconocer el miedo de otra persona y conservar su derecho a pedir ayuda y explicar lo ocurrido. La discusión termina; lo que autorices hacer con contratos y recuerdos aún tiene consecuencias.','La pregunta no obliga a elegir entre crueldad e impunidad. Una explicación puede orientar una reparación sin borrar el daño.','argument')
  ],
  after:['Conservás los nombres y retirás los contratos del horno. Abren las habitaciones que aún faltan y cada huésped puede elegir la salida; después comienzan a devolver frascos identificados. Algunos recuerdos necesitan más búsqueda. Rosa deja las llaves en la mesa y acepta ir a la posta a consultar por su hermana, sin una promesa sobre lo que encontrarán.','Abrís la salida, pero conservás algunos contratos para exigir cooperación. Nadie obtiene por eso un derecho a encerrar de nuevo a quien ya salió. La amenaza sobre los recuerdos continúa en un bolsillo nuevo: Rosa la reconoce y te pide que la devolución no dependa de obedecerte.','Melaza ejecuta el contrato rápido que respaldaste. Los hermanos alcanzan el camino, pero Bruno ya no reconoce quién talló el pájaro que sostiene. No deshacen esa pérdida pronunciando una respuesta correcta. Los frascos que no se restituyeron siguen en el registro y las personas ya liberadas no vuelven automáticamente a sus habitaciones.']
 });
 STORIES[1].chapters[3].docs[1].text='Con el horno apagado y Melaza observada a tu lado, Rosa dice «tengo miedo de que salgan»: el contrato conserva sus letras. Después ordena al Archivero «que nadie elija irse»: la tinta cambia. El registro anota las dos frases, la posición de las personas y que no se encendió el fuego entre ellas. Alma, Bruno y el Archivero lo leen antes de firmar; vos conservás otra copia. El contraste repite lo visto en las dos hojas del archivo. La tristeza no identifica la infección: la alteración se produce junto a una orden que niega una elección.';
 STORIES[1].chapters.forEach(c=>c.docs.forEach(d=>d.text=d.text.replaceAll('durante desayuno','durante la sopa de bienvenida')));
 STORIES[1].chapters[1].repair[0]='El asiento de la sopa de bienvenida';
 STORIES[1].chapters[2].timeline[2]='El Archivero localiza el saco y Rosa autoriza leer sus cartas.';
 STORIES[1].chapters[2].docs[0].text=STORIES[1].chapters[2].docs[0].text.replace('Alma encuentra el saco bajo la escalera.','El Archivero localiza el saco y Rosa autoriza leer sus cartas.');
 const restoreHouse=STORIES[1].chapters[3];
 restoreHouse.debateAfterByChoice[0]=state=>{
  const rooms=state.choices[2]===2?'Con la llave que quedó pendiente, abrís los cuartos de Nico y los otros niños antes de comenzar la devolución.':'Los niños que liberaste del archivo esperan en el vestíbulo; sus puertas continúan abiertas.';
  const letter=state.choices[2]===1?' Le devolvés a Rosa la carta que retuviste y reconocés que no te correspondía condicionar su consulta. No le pedís que agradezca la rectificación.':'';
  return `Conservás los nombres y retirás los contratos del horno. ${rooms} Comienzan a devolver frascos identificados; algunos recuerdos necesitan más búsqueda. Rosa deja las llaves en la mesa y acepta ir a la posta a consultar por su hermana, sin una promesa sobre lo que encontrarán.${letter}`;
 };
 restoreHouse.debateAfterByChoice[2]=state=>{
  const rooms=state.choices[2]===2?'Nico y los otros niños siguen en las habitaciones que no abriste. Su deuda no fue retirada por el trato que hiciste para los hermanos.':'Nico y los niños que liberaste conservan el vestíbulo abierto; no vuelven a encerrarse por el nuevo contrato de los hermanos.';
  return `Melaza ejecuta el contrato rápido que respaldaste. Los hermanos alcanzan el camino, pero Bruno no reconoce quién talló el pájaro que sostiene. No se deshace esa pérdida pronunciando una respuesta correcta. ${rooms} Los frascos que no se restituyeron siguen en el registro.`;
 };

 section(2,0,[
 ['Narrador','La tercera puerta del Archivo se abre en una calle de talleres. Cruzás y comprobás la señal de regreso en tu cuaderno antes de dejar el marco. La música llega desde la plaza vecina. Una muchacha acomoda botones sobre una mesa frente a un local cerrado; observa un anuncio real con más preocupación que entusiasmo.','La calle de los talleres',0],
 ['player','Me llamo {{player}}. Investigo alteraciones en documentos y necesito conocer lo que está pasando acá. ¿Ese anuncio puede leerse o es un aviso privado?'],
 ['Vera','Soy Vera. Es público; nos cobran el desfile a todos. El emperador va a estrenar mañana un tejido que, según los sastres, solo pueden ver las personas sabias. Si no lo ves, te llaman incapaz. Mi madre perdió la licencia del taller por una denuncia parecida.'],
 ['Narrador','Vera señala la puerta cerrada detrás de su mesa. Su madre había comparado fibras y descubierto algodón cobrado como seda. La respuesta del palacio cuestionó su entusiasmo en vez de examinar la muestra. Desde entonces arregla uniformes de noche; Vera vende botones para pagar parte del alquiler.'],
 ['Vera','No quiero que me creas porque me pase algo triste. Conservo una copia de la denuncia. Quiero que alguien la lea, no que me devuelvan el taller a cambio de decir cualquier cosa.'],
 ['Narrador','Un aprendiz de pelo gris llega con una invitación y un cuaderno de dibujo. Vera lo presenta como Tilo, su amigo desde que aprendían a coser compartiendo un dedal. Trabaja como dibujante del palacio y la beca que cobra ayuda a sostener a su abuelo. No venía a certificar la venta; le encargaron ilustrarla.'],
 ['Tilo','Tengo que entregar hoy el vestido completo dibujado. El acceso al telar es después. No sé qué hacer si entro y no veo nada: la orden llama “cooperación satisfactoria” a lo que mantiene mi beca.'],
 ['player','Podemos separar lo que te encargaron imaginar de lo que llegues a observar. ¿Me dejás leer esa orden? No voy a mostrarla en público sin preguntarte.'],
 ['Narrador','Tilo permite leerla y Vera guarda sus botones en una caja antes de acompañarte. Caminan hasta la plaza siguiendo la música. Al pie del escenario hay una mesa de solicitudes: van a registrar allí una petición de revisión y pedir acceso al telar.','La plaza del anuncio',1],
 ['Narrador','Sobre el escenario, un hombre con máscara sostiene dos luces: una indica cuándo aplaudir y otra cuándo asentir. Se presenta como Maestro del Aplauso, encargado de la ceremonia y de recibir las declaraciones del público. Te acercás a su mesa de solicitudes y pedís registrar la duda sobre el tejido.'],
 ['player','Quiero presentar una duda sobre cómo se comprobará el tejido y una denuncia anterior que todavía no recibió respuesta. Vera y Tilo trajeron sus documentos. ¿Quién puede registrar la petición?'],
 ['El Maestro del Aplauso','La archivista Bruna conserva las actas. Ahí está, junto al atril. Pero las dudas se presentan después de demostrar confianza en el emperador. Una declaración de admiración bastaría para reabrir aquel taller. No tienen que nombrar ninguna tela.'],
 ['Narrador','Bruna se acerca al oír la palabra «taller». Vera saca de su bolso la carta que te mostró frente a su casa. La archivista reconoce la denuncia y ofrece sellar una copia de la petición, aunque le cuesta mirar a Vera a los ojos. Le contás también que estás buscando alteraciones de tinta; no conoce ningún registro reciente que pueda señalarte.'],
 ['Tilo','Necesito la beca. No puedo prometer que no tenga miedo. ¿Si digo que todavía no observé nada, me vas a pedir que arriesgue la casa de mi abuelo para demostrar valentía?'],
 ['player','Voy a pedir una revisión que proteja tu testimonio de represalias. Eso no garantiza que el palacio acepte. Tampoco voy a usar tu necesidad como prueba de que existe una tela. Vos elegís qué documento querés firmar.'],
 ['Narrador','La diferencia importa a Vera: puede defender su taller sin exigir a su amigo una valentía que ella no paga. Te enseña su copia de la denuncia y la muestra de fibras que acompaña. La carta pide corregir material y precio; no exige que nadie deje de encontrar bello el algodón.'],
 ['El Maestro del Aplauso','Todo esto sería más fácil con una frase amable. Si todos los sabios ven el tejido, admitir que no lo ven solo perjudica a quien lo dice. ¿Por qué convertir una fiesta en un problema?'],
 ['Narrador','Tenés un desacuerdo delimitado. El Maestro condiciona el acceso a una declaración y pretende usar el futuro dibujo como prueba independiente. Vos necesitás que responda a la convocatoria y a la orden de entrega antes de que las publique como testimonios de una observación que nadie hizo.'],
 ['player','Voy a contrastar esas afirmaciones con los papeles que trajeron. La petición no supone que ya conozcamos al portador de La Errata. Pide comprobar una venta y evitar que una amenaza sobre la beca se convierta en una descripción del telar.'],
 ['Narrador','Bruna coloca en la mesa la convocatoria pública y registra que Vera aportó la carta y Tilo permitió examinar su orden. El emperador observa desde un balcón lejano; todavía no habló con ustedes. La discusión inmediata será con el responsable de la ceremonia, no con todas las personas del palacio a la vez.']
 ],{
  anchor:8,
  investigation:'Las tres fuentes tienen un origen: el anuncio público, la orden que Tilo mostró con permiso y la copia que Vera conservaba de la denuncia de su madre. Compará qué prometen y qué ocurrió antes de cualquier observación del telar.',
  question:'El Maestro exige una declaración para registrar la petición. ¿Qué respuesta respaldás ante Vera y Tilo?',
  options:['Pedir revisión de las pruebas y protección para describir lo observado sin elogios obligatorios.','Elogiar el esfuerzo del palacio sin nombrar la tela para conseguir primero una autorización.','Declarar perfecto el tejido y presionar a Tilo para dibujarlo sin hacer preguntas.'],
  intent:['Pedís registrar la duda sin castigar a quien la expone. El Maestro aún pretende usar su regla como garantía; tenés que mostrar qué puede comprobarse y qué no.','Ofrecés un elogio general para ganar acceso. Vera advierte que puede imprimirse junto a la venta. La discusión debe precisar qué respaldo están intentando obtener de tu frase.','Avalás la perfección sin haber visto material. Tilo se siente presionado por otra persona además del palacio. El Maestro intenta usar la declaración para cerrar las preguntas que aún no respondiste.'],
  debate:{opponent:'El Maestro del Aplauso',portrait:portrait('El Maestro del Aplauso','traje',2),reason:'El Maestro quiere que elogiar sea condición para comprobar y trata un encargo previo como si fuera observación independiente. Vos necesitás un registro que permita discutir los hechos sin ese requisito.',opening:'Vos interrogás al encargado de la ceremonia. Vera conserva su denuncia; Tilo decide sobre su orden de dibujo; Bruna anota respuestas. Nadie tiene que fingir que una necesidad económica demuestra la existencia de tela.',finding:'La convocatoria no admite una prueba independiente, el dibujo se encargó antes de visitar el telar y la denuncia de fibras no se respondió hablando del carácter de su autora. La petición de revisión puede registrarse con esas diferencias.',infection:'Se identificaron presión y razonamientos que evitan comprobar una venta. No hay todavía una alteración de tinta observada en este mundo; eso impide atribuir automáticamente el foco al Maestro.'},
  rounds:[
   round('El Maestro del Aplauso','«No verlo demuestra incapacidad; cualquier persona capaz lo ve». El Maestro usa la misma regla para afirmar la tela y descalificar cualquier resultado contrario.',['El anuncio no propone qué observación admitiría que la venta fuera falsa.','Obedecer siempre mide la sabiduría.','Imprimir la regla demuestra que hay material.'],0,0,'Le pedís una forma de contrastar la promesa que no dependa de aceptarla. El Maestro no puede señalarla en la convocatoria. Bruna registra esa limitación, sin convertir la duda en una prueba de incapacidad.','Preguntá qué resultado podría hacer revisar la afirmación. Una regla que siempre se confirma no comprueba lo que vende.','argument'),
   round('El Maestro del Aplauso','El Maestro muestra el cuaderno: «Tilo ya es un testigo independiente del tejido». Tilo recuerda que aún no entró al taller.',['El dibujo puede describir una observación futura como si ya hubiera pasado.','La orden fija la entrega antes de la visita: es un encargo, no un testimonio directo.','Una beca hace visible cualquier material.'],1,1,'Presentás la orden con permiso de Tilo. Las fechas separan el encargo y la observación; la dependencia de su beca también debe quedar registrada. El Maestro retira la palabra “independiente”.','Buscá la fuente que fija cuándo debe entregarse el dibujo y cuándo puede entrar al telar.','evidence'),
   round('El Maestro del Aplauso','«La madre de Vera odiaba la belleza; por eso se quejó», insiste el Maestro. Evita así comparar las fibras con la factura.',['El entusiasmo cambia el material de una muestra.','La carta pide destruir todos los talleres.','La carta cuestiona material y precio; una acusación sobre su carácter no responde esas pruebas.'],2,2,'Vera puede leer su petición completa. Bruna anota que se devolvió sin responder la comparación de fibras. No se decide una licencia por simpatía: se recupera una pregunta que había quedado tapada por otra acusación.','Respondé a lo que la carta reclama. Pedir un precio correcto no implica negar que el algodón pueda ser bello.','argument')
  ],
  after:['Bruna registra tu petición y conserva copias con Vera y Tilo. El taller no reabre por un elogio, pero el Maestro autoriza el acceso al telar para no dejar el encargo sin una comparación. Pedís incluir la amenaza sobre la beca en el expediente.','El Maestro imprime tu elogio junto al anuncio y entrega a Vera una autorización temporal. No habías descrito la tela; ahora tu frase aparece respaldando su presentación. Conseguís entrar al taller con esa diferencia pendiente de aclarar.','Tilo termina bajo tu presión un dibujo imaginado y lo firma ante la mesa. El Maestro lo exhibe junto a tu declaración como si el aprendiz hubiera observado el tejido. Vera consigue una promesa sobre la licencia y Tilo entra al telar después de que su firma ya empezó a circular. La presión que respaldaste forma parte de lo que van a encontrar.']
 });

 section(2,1,[
 ['Narrador','Bruna te acompaña desde la plaza hasta el palacio con la autorización que obtuvieron. La muestra a la guardia y los guía por la escalera del primer piso. Vera y Tilo caminan con vos. El Maestro los recibe en la puerta del taller y permanece junto al atril destinado a los testimonios.','La escalera del taller real',0],
 ['Narrador','Al entrar ves dos bastidores, canastas vacías, pesas de comparación y un espejo limpio junto a la ventana. Los sastres mueven las manos sobre los bastidores. Oís madera golpeando madera; todavía no afirmás que ese sonido demuestre un material. Tilo se acerca para observar antes de hablar.','El taller del telar',1],
 ['Tilo','No distingo hilo. Puedo oír las lanzaderas, pero no veo material entre ellas. Eso es lo que puedo anotar hoy, aunque me cueste decirlo.'],
 ['player','Escribilo con tus palabras. Voy a registrar qué observaste y cuándo. No hace falta inventar una certeza sobre todo lo invisible para comprobar la promesa concreta de estos vendedores.'],
 ['Narrador','Bruna abre una caja de muestras y una balanza. La venta prometía hilo real cobrado por peso; por eso el peso del bastidor puede contrastarse. Vera pide no tocar la máquina hasta anotar el valor vacío que figura en la placa. Los sastres aceptan medir delante de la archivista y de la guardia de sala. Bruna equilibra la balanza con las pesas indicadas para el bastidor vacío; al apoyar el supuesto tejido, la aguja no se mueve. Repetís la lectura y la guardia la anota. Una muestra sellada tampoco contiene hilo: al abrirla delante de todos, solo queda el envoltorio.'],
 ['Narrador','El emperador entra por una puerta interior. Bruna lo presenta por su nombre: León. Es un hombre mayor con tinta en un puño. Al ver que Tilo se acerca mucho a la hoja, pregunta si las lentes le sirven. El aprendiz se las acomoda y admite que la patilla está torcida desde hace semanas. León le ofrece una silla junto a la ventana.'],
 ['León','El sol da de frente. Tal vez por eso no ven bien. Prueben desde acá. Quiero que todos tengan permiso para disentir. Lo voy a dejar escrito.'],
 ['Narrador','El cambio de lugar no muestra un hilo nuevo. León escribe la frase prometida. Bruna pide una copia para el registro de la visita y la lee en voz alta antes de que el emperador lleve el original al balcón. Vera recibe el duplicado; vos anotás quién conserva cada hoja.'],
 ['Narrador','El Maestro reparte hojas: cada asistente debe describir lo observado. Tilo escribe que no ve hilos; la guardia distingue el sonido del material; un comerciante anota que le ordenaron describir oro. Te dejan leer sus frases cuando pedís permiso. Luego entregan las hojas al Maestro.'],
 ['El Maestro del Aplauso','Voy a reunirlo en un acta breve. Así el público no se confunde con tantas versiones distintas de una misma experiencia.'],
 ['Narrador','Cuando vuelve el acta impresa, dice que todos admiraron «el oro que recuerda el amanecer». Es la frase del anuncio. Ninguno de los originales que leíste decía eso. Bruna solicita devolver los papeles a sus autores y guarda una copia del resumen con la firma que ordenó imprimirlo.'],
 ['player','No voy a decidir que hubo unanimidad porque el resumen lo diga. Quiero contrastarlo con las hojas originales delante de quienes las escribieron.'],
 ['Narrador','León regresa con su nota. Antes de entregarla exige que nadie lo contradiga en público. La palabra «disentir» empieza a convertirse en «asentir». Vos le pedís no soltar el papel hasta que Bruna anote la hora; Vera conserva la copia sin cambio lejos de él. El Maestro sigue visible junto a la balanza.'],
 ['León','Debe ser tinta barata. Yo escribí lo contrario. No sé por qué quedó así.'],
 ['player','Vamos a conservar lo que observamos sin afirmar todavía una causa. Bruna, anotá quién tenía cada hoja y qué dijo cada persona. Necesitaremos otro contraste antes de señalar un foco.'],
 ['Narrador','La guardia confirma las posiciones que vio. Anotás por separado el acta impresa y el cambio de la nota. Bruna guarda los originales de los testimonios en una carpeta y la hoja de León en otra; Vera comprueba que el duplicado que recibió sigue diciendo «disentir».'],
 ['Bruna','Debí pedir esa comparación cuando la madre de Vera denunció el algodón. Guardé las muestras, pero no defendí su derecho a que las leyeran. Pensé que podía servir mejor quedándome en el archivo. Eso no le devolvió el trabajo.'],
 ['Vera','Quiero que guardes también aquel expediente. Conservaste las muestras, pero mi madre tuvo que cerrar igual. Si querés explicarle por qué callaste, te acompaño a hablar con ella. No puedo prometerte qué va a responder.'],
 ['Tilo','Podés usar mi descripción si también registran que la beca no debe depender de un elogio. No quiero que escondan la verdad para salvarme; tampoco que me usen como si el alquiler de mi abuelo no importara.'],
 ['Narrador','El Maestro impide sustituir el resumen hasta que le demuestres que tergiversa lo entregado. Tenés una razón para confrontarlo y las fuentes están en la misma sala: originales, medición y copia de la nota. Vas a decidir cómo usar el testimonio de Tilo, sin hacer pasar la elección por una observación que no le pertenece.']
 ],{
  anchor:1,
  routes:['Tilo llega con dos columnas en su cuaderno: lo que le encargaron y lo que observó. La petición que respaldaste permite preguntarle por ambas sin fingir que el encargo ya era un testimonio.','Sobre el atril está el elogio general que ofreciste en la plaza. El Maestro lo llama apoyo espontáneo al tejido. Aclarás ante Bruna que no habías visto material, aunque esa precisión no borre la autorización temporal que Vera aceptó.','El dibujo que presionaste a Tilo a completar se expone como prueba de lo que todavía no había visto. El muchacho mira su firma antes de entrar. La demostración comienza con un perjuicio que tu propia intervención ayudó a producir.'],
  investigation:'Todos siguen en el taller. Los autores permiten comparar sus hojas con el acta impresa, la balanza comprueba la propiedad vendida por peso y Bruna conserva la nota junto a una copia anterior. Leé cada contraste sin convertir la falsificación demostrada en una explicación automática de la tinta.',
  question:'Tilo autoriza presentar su hoja con protección frente a represalias. ¿Cómo usás ese testimonio?',
  options:['Presentarlo con su permiso y registrar la amenaza sobre la beca junto a Bruna y la guardia.','Guardar la hoja para protegerlo y hablar solo de dudas sin mostrar la contradicción.','Publicar la hoja sin respetar sus condiciones y reprocharle el miedo a perder la beca.'],
  intent:['Pedís que el permiso de Tilo y la posible represalia consten antes de publicar. El Maestro insiste en que su resumen es fiel: todavía tiene que responder a la comparación.','Decidís reservar la hoja. Tilo conserva un respiro inmediato, pero te pregunta cómo van a corregir el resumen si nadie ve lo que escribió. La objeción a la falsificación sigue necesitando una fuente.','Usás la hoja sin mantener el límite que Tilo pidió. La prueba no deja de tener contenido por ese abuso, pero él no acepta que su miedo se use para humillarlo. El Maestro tendrá que responder a los documentos y vos al modo de presentarlos.'],
  debate:{opponent:'El Maestro del Aplauso',portrait:portrait('El Maestro del Aplauso','traje',2),reason:'El Maestro quiere mantener como unánime un acta que reemplazó las observaciones y usa una promesa de invisibilidad para evitar la prueba de peso que la propia venta permite.',opening:'Vos mostrás las diferencias ante el responsable de impresión. Tilo habla por su hoja, Bruna y la guardia conservan los originales, León mantiene la nota alterada sin sustituir ese hecho por una explicación ya probada.',finding:'El resumen no reproduce las observaciones y la balanza no registra el material prometido. El Maestro reconoce su intervención sobre el acta. Esa falsificación no demuestra quién activó el cambio de «disentir» a «asentir».',infection:'Existe una primera alteración junto a León tras una orden de obediencia, pero falta contrastarla en otra situación. El fraude de la venta y la edición del resumen conservan responsables aunque el foco pueda ser distinto.'},
  rounds:[
   round('El Maestro del Aplauso','«Las tres firmas prueban que todos describieron el mismo oro», sostiene el Maestro. El resumen puede cotejarse con los papeles que recibió.',['Los originales contienen observaciones distintas que el resumen reemplazó por una frase del anuncio.','Una rima prueba el material vendido.','La guardia no pudo observar porque llevaba uniforme.'],0,0,'La guardia y el comerciante permiten mostrar sus originales: ninguno escribió el elogio impreso. Esa comparación basta para refutar la supuesta unanimidad, incluso si decidiste reservar la hoja de Tilo. El Maestro admite haber uniformado las descripciones para la impresión. Ya no puede presentar esa uniformidad como un resultado observado por tres personas.','Compará las palabras originales. Varias firmas al pie de un resumen no demuestran que ese resumen reproduzca lo que cada cual escribió.','evidence'),
   round('El Maestro del Aplauso','El Maestro intenta cerrar la medición: «Lo invisible no puede comprobarse». La factura y la explicación de los sastres prometían hilo real cobrado por peso.',['La música equivale al peso de un tejido.','La masa añadida que prometieron puede medirse aunque discutan el color o la visibilidad.','No hace falta comprobar ninguna propiedad de una venta.'],1,1,'Presentás la placa de peso vacío y el resultado idéntico de la balanza. No discutís todas las cosas invisibles posibles: comprobás la propiedad concreta que estos vendedores cobraron.','Buscá qué propiedad prometieron. Si venden un material por peso, esa afirmación tiene un contraste delimitado.','evidence'),
   round('El Maestro del Aplauso','«Si yo cambié el resumen, también debo ser el responsable de cualquier letra que se mueva», dice el Maestro. Quiere un único expediente que deje fuera el momento de la nota.',['La confesión de una falsificación demuestra cualquier alteración mágica.','Las máscaras identifican focos sin documentos.','La falsificación y el cambio de la nota son hechos distintos: hay que conservar el registro del balcón y repetir el contraste.'],2,2,'Separás la orden de impresión y el cambio observado. El Maestro reconoce lo que hizo sin obtener por ello el poder de explicar cualquier otro fenómeno. Bruna preserva ambos expedientes.','Una responsabilidad concreta no sustituye la prueba de otra. Atendé a quién tuvo acceso, qué cambió y cuándo.','argument')
  ],
  after:['Tilo firma una copia con sus condiciones. Bruna y la guardia registran la amenaza de la beca y conservan las hojas antes de salir. El acta puede discutirse en la plaza con fuentes disponibles, no solo con una denuncia contra la cara del Maestro.','Tilo conserva su hoja guardada. Llevás el acta cuestionada y la medición, pero el público todavía no podrá ver su testimonio personal. La diferencia entre proteger un límite y mantener una versión incompleta queda en el expediente.','La hoja circula sin el límite que Tilo pidió. El contenido permite comprobar la falsificación, pero el muchacho camina separado de vos y Vera al salir. Haber presentado una prueba verdadera no te devuelve automáticamente su confianza.']
 });
 section(2,2,[
 ['Narrador','Al salir del taller Bruna conserva las copias en su archivo, con constancia de quién entregó cada una. No pueden convocar a toda la plaza esa misma tarde: el desfile está anunciado para la mañana siguiente. Vera te ofrece esperar en la posada de su calle; Tilo vuelve a comprobar cómo está su abuelo. Antes de separarse acuerdan encontrarse con Bruna al pie del escenario.','La calle al anochecer',0],
 ['Narrador','A la mañana siguiente regresás con Vera a la plaza. La madre de Vera espera junto a un puesto de abrigos y te agradece que hayan conservado su denuncia. Le dice a su hija que puede volver a casa aunque nadie la escuche. Vera se deja acomodar el cuello antes de acercarse al escenario.','Las escalinatas del desfile',0],
 ['Narrador','Tilo y Bruna llegan con la guardia que observó la prueba. Le preguntás al aprendiz si quiere sostener otra hoja durante un contraste de tinta. Espera a escuchar el procedimiento antes de aceptar: participar de esta comprobación no decide si vuelve a confiar en el uso que hicieron de su testimonio anterior.'],
 ['player','Ayer vimos un cambio cerca de León. Hoy vamos a comparar una petición lejos y cerca de él, sin permitir que el Maestro la toque. Nadie tiene que decir lo que no piensa para que un papel nos dé la razón.'],
 ['Bruna','Los talleres entregaron una petición de revisión. Vamos a copiarla antes de mostrar el original. Si la tinta cambia, registraremos quién estaba cerca y qué se dijo. La factura del desfile quedará aparte para no tratar dos hechos como si fueran uno.'],
 ['Narrador','La guardia y Tilo leen la petición con Bruna. Vos pedís a León que permita el contraste antes de la fanfarria; el emperador acepta porque aún atribuye el episodio anterior a tinta barata. Vera conserva una copia a doce pasos y Tilo sostiene el original lejos del balcón. No cambia.','La mesa de la petición',1],
 ['León','Que pueda revisarse no significa que deban hacerme quedar mal. Acerquen esa hoja. Que nadie vuelva a criticarme delante de la plaza.'],
 ['Narrador','Cuando León se acerca y exige evitar críticas, la palabra «revisión» comienza a sustituirse en el original. Le pedís apartarse sin cambiar de mano la hoja; el avance se detiene. El Maestro y los sastres permanecieron visibles sin tocar los documentos. Bruna, Tilo y la guardia firman lo que observaron.'],
 ['player','Vamos a conservar esa comparación y la de ayer. No necesitamos decidirlo por el vestido, por una sonrisa ni por cuán amable parece alguien. El cambio se relaciona con una posición y una orden que quedaron registradas.'],
 ['Narrador','El Maestro llama a los músicos y enciende la señal de aplauso antes de que se presente el tejido. Una niña del público, Luma, pregunta qué están celebrando si el escenario aún está vacío. Su padre le pide callar mirando a la guardia. Tilo reconoce la mirada y cierra la mano alrededor de su cuaderno.'],
 ['Vera','Quiero mostrar lo cobrado y lo observado. Si empiezo riéndome de León, pueden convertirlo todo en una ofensa y no escuchar el dinero que falta en los talleres.'],
 ['Narrador','Bruna consiguió la factura y el inventario durante la noche, usando su cargo de archivista y dejando copia de la solicitud. Los pone ante vos. Cobran seda real que nunca figura entre las cargas recibidas; el pago salió del fondo destinado a reparar talleres como el de la madre de Vera.'],
 ['El Maestro del Aplauso','Si quieren hablar, háganlo al terminar. Ahora el público necesita una fiesta. No vamos a arruinarla con papeles que nadie entiende.'],
 ['player','Los papeles pueden explicarse. La factura dice qué se cobró y el inventario qué llegó. Voy a pedir que se escuchen las dos cosas antes de usar la alegría del público como si verificara un gasto.'],
 ['Narrador','El Maestro propone culpar a los sastres, suspender la exposición y cerrar la revisión. Tilo pregunta por la beca y una vecina por el dinero de su taller. La propuesta no contesta esas dos preguntas. Vera te muestra la petición que los propios trabajadores firmaron, con desacuerdos incluidos.'],
 ['Bruna','Antes de leer las firmas tengo que decir algo. El sello de “falta de entusiasmo” en la carta de tu madre lo puse yo, Vera. Seguí la instrucción del Maestro para conservar mi puesto. Guardar las fibras después no deshizo lo que hice. Dejé mi declaración junto a la petición; tu madre reconoció la muesca del sello y Tilo comprobó el registro. Voy a leerla también ante la plaza. Después leeremos qué piden los talleres: devolver lo mal cobrado y poder objetar sin perder el oficio.'],
 ['Narrador','Vera quiere acompañarte al frente. No te entrega su voz para que la reemplaces: va a describir su denuncia mientras vos presentás el contraste de fuentes. La madre escucha desde la segunda fila. León espera detrás del telón y el Maestro controla el turno de la fanfarria.'],
 ['player','Antes de llamar al público, voy a responder al cierre que ofrece el Maestro. Ganar la atención no nos permite escoger un culpable por su apariencia ni exigir que todos repitan lo mismo. Tenemos cuentas, una prueba de tinta y una petición que se pueden explicar por separado.']
 ],{
  anchor:2,
  routes:['Vera lleva la petición que registraron sin un elogio obligatorio. El Maestro no puede tratarla como una retractación repentina de un respaldo que nunca dieron. Tilo reconoce esa diferencia aunque siga temiendo por su beca.','El elogio general de la primera visita sigue impreso junto al anuncio. Al preparar la intervención admitís ante Bruna que esa frase no certificaba una observación. Necesitás explicar su uso en público, no esconderlo al acusar a otros de recortar testimonios.','La firma del primer dibujo continúa al pie de una tela que Tilo no vio antes de representarla. Vera guarda una copia de la orden. Si querés corregir la falsificación, tenés que reconocer también la presión que respaldaste en la plaza.'],
  echoes:['Bruna y la guardia llegan con el testimonio autorizado de Tilo. La amenaza sobre la beca está registrada: pueden hablar de proteger a un testigo a partir de lo que pidió, no de una valentía que vos le atribuyas.','Tilo mantiene guardada su hoja original de ayer. La medición y los testimonios de la guardia y el comerciante pueden explicarse sin publicarla; la plaza todavía no conoce su declaración personal. El nuevo ensayo requiere un permiso distinto, que estás por pedirle.','Tilo deja su cuaderno al lado de Bruna y mantiene una silla entre vos y él. Escucha la propuesta de comparación sin que eso borre la publicación que hiciste contra sus condiciones. Tu expediente conserva una prueba y una ruptura de confianza.'],
  investigation:'La reunión pública empieza después de la noche de preparación. Bruna aporta factura e inventario, tres lectores conservan el segundo ensayo y los talleres entregan su petición. Leé antes de decidir cómo abrir una discusión que puede detener el desfile o limitarse a una denuncia incompleta.',
  question:'El Maestro prende la señal para que el público aplauda sin escuchar. ¿Cómo intervenís con Vera?',
  options:['Mostrar las cuentas y los originales y pedir turnos para escuchar las pruebas antes de responder.','Señalar el engaño del traje sin nombrar las amenazas ni reclamar revisión de los fondos.','Promover la burla de León y pedir que la plaza repita una acusación sin contrastarla.'],
  intent:['Pedís una pausa para que Vera presente su denuncia y el público pueda comparar fuentes. El Maestro se opone a interrumpir la fanfarria; vas a responder por qué su propuesta de cerrar el caso no basta.','Limitás la intervención al tejido ausente. El Maestro ofrece expulsar a los sastres y dar el asunto por terminado. Vera te pide no confundir esa medida con la reparación de todo lo que quedó en los papeles.','Abrís con una burla y parte de la plaza la repite antes de escuchar. El Maestro usa ese ruido para desacreditar cualquier pregunta posterior. Todavía debés responder con pruebas y hacerte cargo del tono que acabás de promover.'],
  debate:{opponent:'El Maestro del Aplauso',portrait:portrait('El Maestro del Aplauso','traje',2),reason:'El encargado del desfile quiere sustituir la revisión por una fiesta o una expulsión limitada. Vos necesitás que el público pueda comparar gastos, alteraciones y medidas sin nuevas órdenes de unanimidad.',opening:'Vos discutís el cierre propuesto por el Maestro; Vera presenta el expediente de su madre. Bruna, la guardia y Tilo responden por el ensayo que acaban de realizar. La plaza puede escuchar y preguntar, no funciona como una única voz que deba obedecerte.',finding:'La alegría del desfile no comprueba la factura; la segunda prueba vincula la tinta con León, no con una ropa sospechosa; la petición admite desacuerdos y exige reparación revisable. El caso debe llegar al consejo con esas preguntas conservadas.',infection:'El segundo ensayo, comparado con la nota del taller, sostiene un foco junto a las órdenes de León. La edición ordinaria del acta sigue vinculada al Maestro. La apariencia de uno y el cargo del otro no reemplazan esos contrastes.'},
  rounds:[
   round('El Maestro del Aplauso','«Si la fiesta nos hizo felices, revisar lo cobrado solo puede perjudicarla». La factura y el inventario describen una diferencia concreta.',['Disfrutar de una fiesta no demuestra que se haya entregado el material que se cobró.','Toda celebración demuestra un fraude.','Un aplauso agrega seda al inventario.'],0,0,'Explicás material, carga y fondo de pago sin pedir que el público deje de sentir alegría. Varias personas bajan las manos para leer. El Maestro debe responder a esa diferencia, no a una emoción que nadie está prohibiendo.','Compará lo facturado con lo recibido. No hace falta condenar toda fiesta para comprobar un gasto.','argument'),
   round('El Maestro del Aplauso','El Maestro acusa a los sastres de ser el foco por su aspecto. Vos pedís ordenar lo observado en el segundo ensayo antes de aceptar esa explicación.',['El original no cambia cuando Tilo lo sostiene lejos de León.','León se acerca y exige evitar críticas.','La sustitución avanza; se detiene cuando León vuelve a apartarse.'],0,1,'El orden conserva qué condición cambió mientras los demás permanecían observados. Junto al ensayo del taller, aporta una relación que las ropas de los sastres no prueban.','Ordená los pasos del acta. No incluyas una acusación por apariencia como si fuera una observación registrada.','sequence'),
   round('El Maestro del Aplauso','«Entonces repitan todos esta misma acusación y ya tendremos una verdad nueva», propone el Maestro. Los talleres piden otro procedimiento.',['Una causa buena justifica prohibir cualquier pregunta.','Si hay desacuerdo no se puede investigar nada.','La petición conserva fuentes y permite cuestionarlas, incluso a quienes presentan la denuncia.'],2,2,'Leés el derecho a objetar y pedís que las preguntas sigan registrándose. El Maestro pierde la justificación para cerrar la discusión con otra señal de aplauso. El consejo tendrá que recibir actas, no solo el ruido de una plaza.','El propósito no es cambiar quién ordena una frase unánime. Buscá cómo la petición permite comprobar y corregir.','argument')
  ],
  after:['Bruna solicita una sesión en el consejo y adjunta cuentas, originales y ensayos con sus firmas. La plaza escucha a Vera y a quienes preguntan después. León acepta recibir el expediente; la protección de los testigos y la devolución de fondos llegan como asuntos concretos, no como un aplauso a tu persona.','El desfile se suspende y el consejo acepta discutir la venta del traje. Llevás un reclamo limitado: fondos, becas y represalias todavía necesitan quedar incluidos. Vera acompaña el expediente sin fingir que todos los talleres ya fueron escuchados.','La burla interrumpe la ceremonia. El consejo recibe un expediente atravesado por el ruido que promoviste; Tilo distingue las pruebas de la acusación repetida por miedo. Los documentos permiten seguir, pero no convierten el trato de la plaza en una reparación justa.']
 });
 STORIES[2].chapters[2].rounds[1].sequence=['El original no cambia cuando Tilo lo sostiene lejos de León.','León se acerca y exige evitar críticas.','La sustitución avanza; se detiene cuando León vuelve a apartarse.'];
 STORIES[2].chapters[2].rounds[1].challengePrompt='Reconstruí el contraste de distancia y orden del acta. Los sastres permanecieron observados sin tocar las hojas.';

 section(2,3,[
 ['Narrador','Bruna entrega a la guardia la convocatoria de la audiencia que aceptó León después de la discusión pública. La guardia comprueba los nombres y deja pasar a Vera, Tilo y a vos con el expediente. La madre de Vera entra detrás para responder por su denuncia. Siguen a Bruna hasta la mesa del consejo.','El corredor del consejo',0],
 ['Narrador','León dejó vacío el trono alto y se sienta en una mesa de trabajo. Eso no cambia por sí solo las leyes, pero permite colocar documentos ante él sin arrodillarse. El Maestro trae un borrador que atribuye el descubrimiento del fraude a la lucidez del emperador y prohíbe más preguntas sobre la contratación.','La mesa del consejo',1],
 ['León','Quiero terminar esto. Los sastres engañaron a todos. Si los expulso y devuelvo la licencia de ese taller, podremos decir que el asunto está reparado.'],
 ['player','Voy a leer el borrador con las pruebas que faltan. La expulsión no devuelve por sí sola los fondos ni responde por las amenazas. También necesitamos una explicación de las órdenes que activaron la tinta cerca de vos.'],
 ['Narrador','León abre un cajón y entrega cartas de su hermana. Te pide leer una que siempre interpretó como abandono. Su hermana dejó el consejo porque sus objeciones no quedaban registradas; escribió que lo quería y quería poder volver sin fingir que él siempre tenía razón. La anotación del emperador agrega una exigencia que la carta no contiene.'],
 ['León','Pensé que, si seguía contradiciéndome delante de todos, no podía estar de mi lado. Después empecé a pedir que no se publicaran esas objeciones. Las palabras cambiaban con más facilidad cuando yo lo ordenaba.'],
 ['player','Podés querer a tu hermana y seguir respondiendo por prohibir su desacuerdo. No vamos a usar la carta como una absolución ni como una prueba de que todo lo hiciste sin elegir. Hay dos ensayos que muestran cuándo cambió la tinta.'],
 ['Narrador','Bruna coloca las actas junto a la nota del cajón. Tilo lee la copia sin dejar que la acerquen a una nueva orden de silencio. La guardia verifica las firmas. El Índice admite una hipótesis sostenida por dos fuentes, pero no sustituye tu responsabilidad al elegir qué persona señalar y por qué.'],
 ['El Maestro del Aplauso','Puedo identificar a los sastres y devolver el dinero si dejamos la beca y las licencias fuera del texto. No tiene sentido seguir castigándonos entre nosotros.'],
 ['Vera','Quiero una revisión que no dependa de un favor a mi familia. Hubo otros talleres. Mi madre puede responder por su carta, no firmar que todos deban quedarse callados para que vuelva a abrir nuestra puerta.'],
 ['Narrador','León pide al secretario dos propuestas. Una ofrece una excepción revocable para la madre de Vera. La otra exige pruebas al revisar licencias, admite apelaciones y conserva los expedientes. Bruna firma la obligación de guardar también los documentos que acreditan sus propias omisiones.'],
 ['Bruna','No voy a usar mi ayuda de hoy para afirmar que defendí esa denuncia hace un año. Si la madre de Vera quiere preguntarme por qué callé, tiene derecho a hacerlo.'],
 ['Narrador','La mujer responde que primero quiere oír cómo recuperarán el dinero y quién impedirá otra retirada sin pruebas. No está obligada a perdonar a Bruna para que la revisión avance. Tilo deja la orden del primer dibujo sobre la mesa: su beca no debería convertirse en la cláusula silenciosa que cierre el trato.'],
 ['Tilo','Voy a sostener lo que observé. Eso no me vuelve alguien sin miedo ni permite que otra persona vuelva a publicar mis cosas sin preguntarme.'],
 ['Narrador','El borrador intenta cerrarse con «y todos estuvieron de acuerdo». Tres lectores comparan la versión abierta y la preservan antes de que la sustitución termine. León escucha que no todos aceptan su relato. Vos le pedís distinguir una discrepancia sobre lo ocurrido de una amenaza contra su derecho a hablar.'],
 ['León','Si el consejo me deja sin una sola voz que diga lo mismo que yo, no sé cómo voy a gobernar. El favor especial es más rápido. ¿Por qué no aceptar lo que pueden recuperar hoy?'],
 ['player','Porque también tenemos que leer qué puede retirarse mañana. Voy a discutir las propuestas con vos. Después el acuerdo quedará sujeto a lo que decida cada parte, no a una frase de unanimidad que oculte el precio.'],
 ['Narrador','La madre de Vera apoya su denuncia junto al comunicado. Vera pasa un dedo por la puntada con que reparó aquel papel. Su madre le acomoda una esquina que amenaza con soltarse y le dice que todavía conserva la aguja. Las dos esperan a que el secretario termine de copiar los pedidos de revisión sobre las fibras, el precio y la licencia.'],
 ['Narrador','El trono continúa vacío mientras la mesa permanece ocupada por personas con preguntas distintas. Tenés delante las cartas, el borrador y las dos propuestas de licencia. Vas a registrar la hipótesis de foco y a decidir qué reparación respaldar antes de responder a los últimos argumentos de León.']
 ],{
  anchor:1,
  routes:['Vera conserva la petición que registraste sin elogiar el tejido. Al sentarse deja ese documento junto al expediente de su madre: la revisión llega con una pregunta que el palacio no pudo convertir en un aval.','El elogio que ofreciste para ganar acceso forma parte del expediente. Lo leés con su contexto antes de pedirle a León que no se atribuya una unanimidad inexistente. Corregir un recorte ajeno no exige esconder el propio.','El primer dibujo y tu presión para presentarlo no desaparecen al llegar al consejo. Tilo acepta sentarse sin ofrecerte una absolución. El acta puede reconocer una prueba verdadera y el costo que le impusiste para usarla.'],
  echoes:['Bruna comprueba que la convocatoria enumere las cuentas, los ensayos y la petición sobre becas y licencias que defendiste en la plaza. La madre de Vera pide su propia copia antes de sentarse: quiere poder señalar cada pregunta cuando le toque hablar.','El reclamo público se limitó al traje. Vera trae ahora la pregunta por los fondos y las represalias para que el consejo no confunda la suspensión de una ceremonia con toda la reparación.','El ruido de la burla alcanzó al consejo antes que ustedes. León intenta usarlo para tratar cada prueba como una ofensa. Debés reconocer el trato que promoviste y mantener, por separado, las fuentes que todavía necesitan respuesta.'],
  investigation:'Las cartas del cajón permiten contrastar la interpretación de León; el borrador muestra qué daños quiere omitir; las dos licencias permiten comparar una excepción revocable con un procedimiento apelable. Todas están sobre la mesa de la audiencia.',
  question:'León pide cerrar el expediente con una reparación. ¿Qué propuesta respaldás?',
  options:['La revisión pública con fuentes, devolución y protección del derecho a disentir.','La devolución del dinero y una licencia especial, reservando los demás reclamos para después.','El relato del emperador a cambio de recuperar enseguida el taller y la beca.'],
  intent:['Pedís que la revisión incluya también límites para quienes la solicitan. León mantiene la oferta del favor rápido y necesitás mostrar qué diferencia hay entre ambas protecciones.','Respaldás una reparación limitada. Vera reconoce el alivio que significaría, pero su madre pregunta por quienes quedarían fuera. Los argumentos no van a decidir que ese límite ya no existe.','Ofrecés cerrar preguntas a cambio del resultado que Vera quería al comienzo. Tilo objeta que su beca se use para imprimir un relato falso. Todavía se puede demostrar qué dicen las propuestas, aunque el precio que aceptaste cambie el cierre.'],
  debate:{opponent:'León',portrait:portrait('León','secondary',2,6),reason:'El emperador quiere sustituir la revisión por un relato que exige obediencia o por un favor revocable. Vos necesitás distinguir afecto, autoridad y garantías antes de que se firme la última versión.',opening:'Vos confrontás los argumentos de León. El Maestro responde por la falsificación que reconoció; Bruna, Tilo, la guardia y la madre de Vera conservan sus propios testimonios. No es una pelea de Vera contra toda una corte ni una condena por el aspecto del emperador.',finding:'La hermana distingue cariño y participación política; suspender el desfile no repara todos los daños; un favor que puede retirarse sin explicación no protege igual que una revisión con apelación. El acuerdo final debe conservar esas diferencias.',infection:'Las dos pruebas de tinta y la comparación de la carta con las órdenes de León sostienen su foco. El Índice bloquea el sello de reescritura sin borrar su voz. Las licencias, los fondos y las responsabilidades ordinarias requieren la reparación que efectivamente se firme.'},
  rounds:[
   round('León','«Mi hermana se fue porque dejó de quererme; por eso tuve que impedir que las críticas separaran a otros», sostiene León. La carta conserva su petición de regresar sin fingir.',['La carta conserva el cariño y rechaza la obligación de estar de acuerdo en el consejo.','Discrepar prueba que no existe afecto.','Una carta de despedida autoriza retirar cualquier voz.'],0,0,'Leés las dos afirmaciones de la hermana. León reconoce que agregó una condición que ella no había escrito. Eso explica una interpretación suya; no justifica convertirla en una regla para los demás.','Separá lo que la hermana pide de lo que León escribió después al margen.','argument'),
   round('León','«Con suspender el desfile ya se repara todo», propone León. El borrador deja fuera consecuencias registradas.',['Una fiesta cancelada devuelve automáticamente todos los fondos.','El expediente incluye dinero, amenazas y licencias que necesitan medidas propias.','Una revisión no puede tener un final.'],1,1,'Mostrás las omisiones del borrador. León no puede presentar una medida sobre la ceremonia como respuesta a cada daño. El secretario deja espacio para registrar obligaciones distintas.','Buscá qué hechos faltan en el relato ofrecido. Detener el engaño visible no devuelve por sí solo cada derecho o pago.','evidence'),
   round('León','León ofrece la excepción: «Es más rápida; por eso protege mejor para siempre». Su propio texto admite revocación sin explicación.',['La rapidez elimina las condiciones de una licencia.','Solo cuenta cuánto tarda el primer alivio.','Hay que comparar quién puede retirarla y qué recurso existe, además de la rapidez.'],2,2,'Comparás las dos propuestas completas. León acepta que una excepción y una garantía apelable no tienen el mismo alcance. Termina la discusión; el resultado material depende del acuerdo que respaldaste, no de que las diferencias hayan desaparecido.','Leé cómo puede retirarse cada protección. “Para siempre” debe poder sostenerse con sus condiciones, no con el tamaño del sello.','argument')
  ],
  after:['La audiencia aprueba una revisión con pruebas y apelación, registra la devolución de fondos y protege a los testigos. La madre de Vera recibe una fecha y una copia; no tiene que agradecer un favor revocable. León conserva voz, pero la copia ya no depende de una orden suya para seguir abierta.','Se devuelven los pagos identificados y el taller recibe una licencia especial. Tilo conserva su beca por ese acuerdo. Quedan fuera otras revisiones y la excepción puede retirarse según su texto: el alivio de la familia no permite anunciar que todos los talleres quedaron protegidos.','El taller y la beca obtienen la promesa inmediata que aceptaste, junto con un comunicado que atribuye el mérito a León y cierra preguntas. Vera puede señalar lo que recuperó; también debe leer lo que firmaron para conseguirlo. El expediente conserva esa diferencia aunque la ceremonia se anuncie como una victoria.']
 });
 // La sombra escribe; el rótulo lo recuerda sin atribuirle una voz inexistente.
 STORIES[0].chapters.forEach(c=>c.narrative.forEach(n=>{if(n.speaker==='Nilo')n.speaker='Nilo · por escrito';}));
 const firstShadow=STORIES[0].chapters[0];
 const soundNote=firstShadow.narrative.find(n=>n.id==='sombra-1-sonido');
 firstShadow.narrative=firstShadow.narrative.filter(n=>n!==soundNote);
 soundNote.text='La campana de bronce sigue colgada. Lo que falta es su voz: un frasco del faro puede retener un sonido y dejar muda la cosa que lo producía. Por eso una campanada guardada puede hacer que el Gran Reloj no reciba su señal, aunque nadie haya arrancado el bronce de la torre.';
 firstShadow.narrative.splice(firstShadow.narrative.findIndex(n=>n.text.startsWith('Mi isla se llama'))+1,0,soundNote);

 // Los tres primeros comprobantes deben conocerse antes de compararlos en el
 // Archivo. Los IDs propios evitan desplazar las anclas de las rutas ya escritas.
 const insertAfter=(chapter,predicate,id,rows)=>{
  const at=chapter.narrative.findIndex(predicate);
  if(at<0)throw new Error('No se encontró el punto de recepción de '+id);
  chapter.narrative.splice(at+1,0,...rows.map(([speaker,text],i)=>({id:id+'-'+(i+1),speaker,text})));
 };
 insertAfter(sound.chapters[2],n=>n.text.startsWith('Pipo se aparta de la mesa'),'sombra-guia',[
  ['player','Pipo, ¿qué más había junto a la copia? Antes de mover la mesa vi una hoja debajo de tu bolso. Quiero anotar qué papeles estaban cerca, sin decidir todavía cuál tuvo relación con el cambio.'],
  ['Pipo','Es una guía que llegó al Reloj hace tres mañanas: «Una promesa de no despedirse». La abrí porque pensé que me enseñaría a escribirle a Mara. Este cuadrito decía “recibido” y puse mi marca. Nadie dijo que fuera a cambiar las cartas de otras personas.'],
  ['Narrador','Pipo te permite leer y copiar la hoja. Tiene el sello del Archivo en la esquina y un pliegue roto en el lugar de su marca. Copiás también el título y la fecha de entrega; Damián los contrasta con el original. Al colocar la grulla a su lado, Lía reconoce una mancha y un sello parecidos. Le pedís a Nilo que explique qué papel usó.'],
  ['Nilo · por escrito','Pipo me dejó una hoja que sobraba en el sobre. Yo no abrí la guía ni marqué su recepción: dibujé en el reverso y doblé la grulla. La marca ya estaba cuando me la dio.'],
  ['Narrador','Guardás aquella explicación con las dos copias. La marca puede viajar en un papel prestado; por sí sola no te dice quién activa una reescritura. Pipo vuelve a guardar su guía. El sello se parece al de tu encargo y queda una pregunta para el Archivo: quién hizo llegar esas hojas a la isla.']
 ]);
 sound.chapters[3].docs[2].text+=' En el muelle Pipo permitió copiar la guía «Una promesa de no despedirse», entregada tres mañanas antes. Conserva el sello del Archivo y su marca de recepción. La copia registra la procedencia de la hoja; los dos contrastes de tinta, no la mera posesión de esa guía, sostienen la hipótesis de foco.';
 insertAfter(STORIES[1].chapters[1],n=>n.text.startsWith('Melaza deja el libro disponible'),'casa-guia',[
  ['Narrador','Al dejar espacio para el dibujo, Rosa aparta una hoja que usaba de mantel individual. Ves un sello del Archivo y le preguntás de dónde salió. Ella la sostiene para que no se manche de sopa antes de responder.'],
  ['Rosa','Llegó entre los avisos de la posta hace una semana. Se llama «Una mesa que nunca quedara vacía». Marqué que la había recibido porque pensé que era una invitación a preparar comidas juntas. Después le pedí al Archivero que copiara aquí mi lista de huéspedes. ¿Por qué tiene un sello como el de tu cuaderno?'],
  ['player','Todavía no lo sé. ¿Me dejás copiar el título, la fecha y esa marca? Quiero preguntar quién la envió. Que tengas una hoja del Archivo no significa que hayas aceptado cualquier cosa que alguien pudiera hacer con ella.'],
  ['Narrador','Rosa acepta y mantiene el original bajo su taza mientras vos copiás el encabezado. Bruno dibuja también dónde quedó la hoja; Melaza sigue en el patio. Al terminar, le devolvés a Rosa el lápiz que te prestó y retomás la lectura del asiento de la sopa.']
 ]);
 STORIES[1].chapters[3].docs[1].text+=' Rosa permitió copiar en la cocina la guía «Una mesa que nunca quedara vacía», recibida una semana antes entre los avisos de la posta. El encabezado conserva el sello del Archivo, la fecha y su marca de recepción. Son datos para rastrear un envío, no una aceptación informada de la facultad de reescribir decisiones ajenas.';
 insertAfter(STORIES[2].chapters[1],n=>n.text.startsWith('El emperador entra por una puerta interior'),'traje-guia',[
  ['Narrador','Una hoja sellada sobresale del libro que León lleva bajo el brazo. Al acomodarlo sobre la mesa, queda a la vista el emblema del Archivo. Le preguntás si puede mostrarte ese encabezado antes de seguir con la demostración del tejido.'],
  ['León','«Una corte sin objeciones». La recibí hace tres días. Creí que era un modelo para dejar de pelear en cada reunión. Marqué la recepción y la guardé con mis notas. Creí que me ayudaría a explicar mejor mis propuestas. No decía que otra persona pudiera hablar en mi nombre.'],
  ['player','Me interesa saber quién la envió, no usar su título como prueba contra vos. ¿Puedo conservar una copia del sello, la fecha y tu marca? Bruna puede comprobar que no copié nada distinto.'],
  ['Narrador','León acepta. Bruna compara tu copia con el encabezado y registra el permiso; el emperador vuelve a guardar el original bajo la tapa de su libro. Anotás que llegó antes de esta visita. Cuando Vera pregunta si van a mostrar el telar desde otro sitio, León señala el rincón donde da menos sol.']
 ]);
 STORIES[2].chapters[3].docs[0].text+=' En el taller León permitió copiar el encabezado de «Una corte sin objeciones», una guía que había recibido tres días antes de aquella visita al telar. Bruna contrastó el sello del Archivo, la fecha y la marca de recepción. Ese envío sirve para investigar la procedencia; identificar el foco exige además los dos ensayos y sus condiciones observadas.';
 STORIES[2].chapters[0].timeline=['Tilo recibe la orden de dibujar.','La orden fija la entrega antes de la visita al telar.','El Maestro invoca la ilustración prevista como testimonio.'];
 STORIES[2].chapters[0].docs[0].text=STORIES[2].chapters[0].docs[0].text.replace('Entrega una ilustración sin ver el telar.','La orden fija la entrega antes de la visita al telar.').replace('El Maestro la presenta como testimonio.','El Maestro invoca la ilustración prevista como testimonio.');
 // Ajustes de procedencia: las fuentes nombran a los testigos presentes y
 // conservan las limitaciones físicas que la escena acaba de establecer.
 garden.docs[1].text=garden.docs[1].text.replace('El Guardián no permite tapar una raya con pintura nueva.', 'Sila añadió una advertencia: no tapar una raya con pintura nueva.');
 STORIES[1].chapters[3].docs[2].text=STORIES[1].chapters[3].docs[2].text.replace('Necesitamos que nos esperes en la posta si el puente sigue cerrado.', 'Vamos a la posta de este lado. Si el puente sigue cerrado, mandanos noticias desde la otra orilla; esperaremos la inspección antes de cruzar.').replace('Añaden un dibujo de nueve patas, porque Nico ayudó a terminarlo.', 'Añaden la copia del dibujo de nueve patas que Bruno trazó en tu cuaderno; el original que completó Nico sigue con él.');
})();
